const substitutionCache:{[key: string]:any} = {};

export function compileSubstitution(str: string): any[] {
	const parts = [];
	let i = 0;
	let l = str.length;
	let part = '';
	let sub = 0;
	while(i < l){
		let chr = str[i++];
		if(chr == '$'){
			let next = str[i++];

			if(next == '$'){
				part += '$';
				continue;
			}
			if(part) parts.push(part);
