{"command": "cat > test/packages/imba-monarch/src/monarch/common.test.js <<'EOF'
import {
  compileSubstitution,
  createError,
  empty,
  findRules,
  fixCase,
  isFuzzyAction,
  isFuzzyActionArr,
  isIAction,
  isString,
  log,
  sanitize,
  stateExists,
  substituteMatches,
  substituteMatchesOld,
} from '../../../../../packages/imba-monarch/src/monarch/common.js';

describe('common type and string helpers', () => {
  test('classifies fuzzy actions, strings, and arrays', () => {
    const action = { token: 'keyword' };

    expect(isFuzzyActionArr([])).toBe(true);
    expect(isFuzzyActionArr([action])).toBe(true);
    expect(isFuzzyActionArr(action)).toBe(false);

    expect(isFuzzyAction(action)).toBe(true);
    expect(isFuzzyAction([action])).toBe(false);

    expect(isString('keyword')).toBe(true);
    expect(isString(action)).toBe(false);

    expect(isIAction(action)).toBe(true);
    expect(isIAction('keyword')).toBe(false);
  });

  test('empty treats all falsy values as empty', () => {
    expect(empty('')).toBe(true);
    expect(empty(undefined)).toBe(true);
    expect(empty(null)).toBe(true);
    expect(empty(0)).toBe(true);
    expect(empty(false)).toBe(true);

    expect(empty('x')).toBe(false);
    expect(empty([])).toBe(false);
    expect(empty({})).toBe(false);
  });

  test('fixCase only lowercases when ignoreCase is enabled', () => {
    expect(fixCase({ ignoreCase: true }, 'MiXeD')).toBe('mixed');
    expect(fixCase({ ignoreCase: false }, 'MiXeD')).toBe('MiXeD');
    expect(fixCase({ ignoreCase: true }, '')).toBe('');
    expect(fixCase({ ignoreCase: true }, null)).toBe(null);
  });

  test('sanitize replaces every token-class unsafe character with a dash', () => {
    expect(sanitize(`a&<>'"_b`)).toBe('a------b');
    expect(sanitize('safe.token-name')).toBe('safe.token-name');
  });
});

describe('common logging and errors', () => {
  test('createError prefixes the lexer language id', () => {
    const error = createError({ languageId: 'demo' }, 'bad rule');

    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe('demo: bad rule');
  });

  test('log writes a single language-prefixed message', () => {
    const originalLog = console.log;
    const calls = [];
    console.log = (...args) => calls.push(args);
    try {
      log({ languageId: 'demo' }, 'compiled');
    } finally {
      console.log = originalLog;
    }

    expect(calls).toEqual([['demo: compiled']]);
  });
});

describe('substitution helpers', () => {
  test('compileSubstitution separates literals and substitution tokens', () => {
    expect(compileSubstitution('a$#$0$1$S0$S1$$b')).toEqual([
      'a',
      0,
      1,
      2,
      100,
      101,
      '$',
      'b',
    ]);
  });

  test('substituteMatches resolves ids, captures, state parts, and escaped dollars', () => {
    const lexer = { languageId: 'demo', ignoreCase: false };
    const result = substituteMatches(
      lexer,
      'id=$#;whole=$0;first=$1;state=$S0;outer=$S1;inner=$S2;dollar=$$',
      'full-match',
      ['whole', 'first', 'second'],
      'outer.inner',
    );

    expect(result).toBe(
      'id=full-match;whole=whole;first=first;state=outer.inner;outer=outer;inner=inner;dollar=$',
    );
  });

  test('substituteMatches treats out-of-range state parts as empty', () => {
    expect(substituteMatches({}, '$S9', 'id', [], 'root')).toBe('');
    expect(substituteMatches({}, 'plain text', 'id', [], 'root')).toBe('plain text');
  });

  test('substituteMatchesOld supports dollar, id, capture, state, and attribute forms', () => {
    const lexer = { languageId: 'demo', ignoreCase: true, base: 'BASE' };
    const result = substituteMatchesOld(
      lexer,
      '$$|$#|$1|$2|$s1|$S2|$@base|$9',
      'ID',
      ['Whole', 'Mixed'],
      'Outer.Inner',
    );

    expect(result.split('|')).toEqual([
      '$',
      'id',
      'mixed',
      '',
      'outer.inner',
      'inner',
      'BASE',
      '',
    ]);
  });
});

describe('state lookup helpers', () => {
  test('findRules resolves exact states and walks up dotted state names', () => {
    const rootRules = [{ regex: /a/ }];
    const childRules = [{ regex: /b/ }];
    const grandchildRules = [{ regex: /c/ }];
    const lexer = {
      tokenizer: {
        'monarch-state-root': rootRules,
        'monarch-state-root.child': childRules,
        'monarch-state-root.child.grandchild': grandchildRules,
      },
    };

    expect(findRules(lexer, 'monarch-state-root')).toBe(rootRules);
    expect(findRules(lexer, 'monarch-state-root.child')).toBe(childRules);
    expect(findRules(lexer, 'monarch-state-root.child.grandchild')).toBe(grandchildRules);
    expect(findRules(lexer, 'monarch-state-root.child.missing')).toBe(childRules);
    expect(findRules(lexer, 'unknown-state')).toBe(null);
  });

  test('stateExists recognizes exact and inherited state names', () => {
    const lexer = {
      stateNames: {
        'state-exists-root': true,
        'state-exists-root.child': true,
      },
    };

    expect(stateExists(lexer, 'state-exists-root')).toBe(true);
    expect(stateExists(lexer, 'state-exists-root.child')).toBe(true);
    expect(stateExists(lexer, 'state-exists-root.child.grandchild')).toBe(true);
    expect(stateExists(lexer, 'other-state')).toBe(false);
  });
});
