    const result = tokenizer.tokenize('HELLO', tokenizer.getInitialState(), 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'word.custom', value: 'HELLO' },
    ]);
    expect(result.tokens[0].language).toBe('editor-mode');
  });

  test('falls back to the default token for each unmatched character', () => {
    const { tokenizer, state } = setup({
      defaultToken: 'invalid',
      tokenizer: { root: [[/[a-z]+/, 'word']] },
    });

    const result = tokenizer.tokenize('ab@$', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'word.runtime', value: 'ab' },
      { offset: 2, type: 'invalid.runtime', value: '@' },
      { offset: 3, type: 'invalid.runtime', value: '$' },
    ]);
  });

  test('emits one default token for an empty line', () => {
    const { tokenizer, state } = setup({
      defaultToken: 'invalid',
      tokenizer: { root: [[/a/, 'letter']] },
    });

    const result = tokenizer.tokenize('', state, 7);

    expect(simpleTokens(result.tokens)).toEqual([
