import { compile } from '../../../../../packages/imba-monarch/src/monarch/compile.js';
import {
  createTokenizationSupport,
  MonarchTokenizer,
} from '../../../../../packages/imba-monarch/src/monarch/lexer.js';
import { Token } from '../../../../../packages/imba-monarch/src/monarch/token.js';

function setup(language, options = {}) {
  const modeId = options.modeId || 'runtime';
  const lexer = compile(modeId, language);
  if (options.configure) options.configure(lexer);
  const tokenizer = createTokenizationSupport(modeId, lexer);
  return { lexer, tokenizer, state: tokenizer.getInitialState() };
}

function simpleTokens(tokens) {
  return tokens.map((token) => ({
    offset: token.offset,
    type: token.type,
    value: token.value,
  }));
}

describe('MonarchTokenizer lifecycle', () => {
  test('creates a loadable tokenizer with an initial root line state', () => {
    const { tokenizer, state } = setup({
      tokenizer: { root: [[/a/, 'letter']] },
    });

    expect(tokenizer).toBeInstanceOf(MonarchTokenizer);
    expect(tokenizer.getLoadStatus()).toEqual({ loaded: true });
    expect(tokenizer.dispose()).toBeUndefined();
    expect(state.stack.state).toBe('root');
    expect(state.stack.depth).toBe(1);
    expect(state.clone().equals(state)).toBe(true);

    const result = tokenizer.tokenize('a', state, 0);
    expect(result.tokens[0]).toBeInstanceOf(Token);
    expect(result.endState.equals(state)).toBe(true);
  });
});

describe('MonarchTokenizer basic tokenization', () => {
  test('emits typed tokens with values, offsets, bracket classes, and postfixes', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/[ \t]+/, ''],
          [/[A-Za-z]+/, 'identifier'],
          [/\d+/, 'number'],
          [/[{}\[\]()]/, '@brackets'],
        ],
      },
    });

    const result = tokenizer.tokenize('abc 12 {x', state, 10);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 10, type: 'identifier.runtime', value: 'abc' },
      { offset: 13, type: '', value: ' ' },
      { offset: 14, type: 'number.runtime', value: '12' },
      { offset: 16, type: '', value: ' ' },
      { offset: 17, type: 'delimiter.curly.runtime', value: '{' },
      { offset: 18, type: 'identifier.runtime', value: 'x' },
    ]);
    expect(result.tokens.every((token) => token.language === 'runtime')).toBe(true);
    expect(result.tokens[0].stack.state).toBe('root');
  });

  test('uses the supplied mode id, token postfix, and ignore-case setting', () => {
    const { tokenizer } = setup(
      {
        ignoreCase: true,
        tokenPostfix: '.custom',
        tokenizer: { root: [[/[a-z]+/, 'word']] },
      },
      { modeId: 'editor-mode' },
    );

    const result = tokenizer.tokenize('HELLO', tokenizer.getInitialState(), 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'word.custom', value: 'HELLO' },
    ]);
    expect(result.tokens[0].language).toBe('editor-mode');
  });

  test('falls back to the default token for each unmatched character', () => {
    const { tokenizer, state } = setup({
      defaultToken: 'invalid',
      tokenizer: { root: [[/[a-z]+/, 'word']] },
    });

    const result = tokenizer.tokenize('ab@$', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'word.runtime', value: 'ab' },
      { offset: 2, type: 'invalid.runtime', value: '@' },
      { offset: 3, type: 'invalid.runtime', value: '$' },
    ]);
  });

  test('emits one default token for an empty line', () => {
    const { tokenizer, state } = setup({
      defaultToken: 'invalid',
      tokenizer: { root: [[/a/, 'letter']] },
    });

    const result = tokenizer.tokenize('', state, 7);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 7, type: 'invalid', value: null },
    ]);
  });

  test('honors rules that only match at the beginning of a line', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/^a/, 'start'],
          [/a/, 'anywhere'],
          [/b/, 'letter-b'],
        ],
      },
    });

    const result = tokenizer.tokenize('aab', state, 0);

    expect(simpleTokens(result.tokens).map((token) => token.type)).toEqual([
      'start.runtime',
      'anywhere.runtime',
      'letter-b.runtime',
    ]);
  });
});

describe('MonarchTokenizer state transitions', () => {
  test('pushes a named state across lines and pops back to the root state', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/"/, { token: 'quote', next: 'string' }],
          [/[ \t]+/, ''],
          [/[a-z]+/, 'identifier'],
        ],
        string: [
          [/"/, { token: 'quote', next: '@pop' }],
          [/[ \t]+/, ''],
          [/[a-z]+/, 'content'],
        ],
      },
    });

    const first = tokenizer.tokenize('say "a', state, 0);
    expect(simpleTokens(first.tokens)).toEqual([
      { offset: 0, type: 'identifier.runtime', value: 'say' },
      { offset: 3, type: '', value: ' ' },
      { offset: 4, type: 'quote.runtime', value: '"' },
      { offset: 5, type: 'content.runtime', value: 'a' },
    ]);
    expect(first.tokens.map((token) => token.stack.state)).toEqual([
      'root',
      'root',
      'string',
      'string',
    ]);
    expect(first.tokens.map((token) => token.stack.depth)).toEqual([1, 1, 2, 2]);
    expect(first.endState.stack.state).toBe('string');

    const second = tokenizer.tokenize('b" done', first.endState, 0);
    expect(simpleTokens(second.tokens)).toEqual([
      { offset: 0, type: 'content.runtime', value: 'b' },
      { offset: 1, type: 'quote.runtime', value: '"' },
      { offset: 2, type: '', value: ' ' },
      { offset: 3, type: 'identifier.runtime', value: 'done' },
    ]);
    expect(second.tokens.map((token) => token.stack.state)).toEqual([
      'string',
      'root',
      'root',
      'root',
    ]);
    expect(second.tokens.map((token) => token.stack.depth)).toEqual([2, 1, 1, 1]);
    expect(second.endState.stack.state).toBe('root');
    expect(second.endState.stack.depth).toBe(1);
  });

  test('pops all nested states at once', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [[/\[/, { token: 'open-root', next: 'nested' }]],
        nested: [[/\{/, { token: 'open-nested', next: 'deep' }]],
        deep: [[/\]/, { token: 'reset', next: '@popall' }]],
      },
    });

    const result = tokenizer.tokenize('[{]', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'open-root.runtime', value: '[' },
      { offset: 1, type: 'open-nested.runtime', value: '{' },
      { offset: 2, type: 'reset.runtime', value: ']' },
    ]);
    expect(result.tokens.map((token) => token.stack.depth)).toEqual([2, 3, 1]);
    expect(result.tokens[2].stack.state).toBe('root');
    expect(result.endState.stack.state).toBe('root');
  });

  test('enforces the maximum stack size', () => {
    const { tokenizer, state } = setup(
      { tokenizer: { root: [[/\[/, { token: 'open', next: '@push' }]] } },
      { configure: (lexer) => { lexer.maxStack = 2; } },
    );

    expect(() => tokenizer.tokenize('[[', state, 0)).toThrow(
      'maximum tokenizer stack size reached',
    );
  });

  test('rejects popping from an empty stack', () => {
    const { tokenizer, state } = setup({
      tokenizer: { root: [[/a/, { token: 'a', next: '@pop' }]] },
    });

    expect(() => tokenizer.tokenize('a', state, 0)).toThrow(
      'trying to pop an empty stack',
    );
  });

  test('resolves a substituted next state at runtime', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [[/\[(\w+)\]/, { token: 'open', next: '$1' }]],
        tag: [[/[a-z]+/, 'name']],
      },
    });

    const result = tokenizer.tokenize('[tag]abc', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'open.runtime', value: '[tag]' },
      { offset: 5, type: 'name.runtime', value: 'abc' },
    ]);
    expect(result.tokens[0].stack.state).toBe('tag');
    expect(result.tokens[0].stack.depth).toBe(2);
  });

  test('reports an undefined substituted next state', () => {
    const { tokenizer, state } = setup({
      tokenizer: { root: [[/\[(\w+)\]/, { token: 'open', next: '$1' }]] },
    });

    expect(() => tokenizer.tokenize('[missing]', state, 0)).toThrow(
      "trying to set a next state 'missing' that is undefined",
    );
  });

  test('switches state without growing the stack and persists the state', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/a/, { token: 'a', switchTo: 'other' }],
          [/./, 'root-character'],
        ],
        other: [
          [/b/, 'b'],
          [/./, 'other-character'],
        ],
      },
    });

    const first = tokenizer.tokenize('ab', state, 0);
    expect(simpleTokens(first.tokens)).toEqual([
      { offset: 0, type: 'a.runtime', value: 'a' },
      { offset: 1, type: 'b.runtime', value: 'b' },
    ]);
    expect(first.tokens.map((token) => token.stack.state)).toEqual(['other', 'other']);
    expect(first.endState.stack.depth).toBe(1);

    const second = tokenizer.tokenize('ab', first.endState, 0);
    expect(simpleTokens(second.tokens)).toEqual([
      { offset: 0, type: 'other-character.runtime', value: 'a' },
      { offset: 1, type: 'b.runtime', value: 'b' },
    ]);
  });

  test('reports an undefined switchTo state', () => {
    const { tokenizer, state } = setup({
      tokenizer: { root: [[/a/, { token: 'a', switchTo: 'missing' }]] },
    });

    expect(() => tokenizer.tokenize('a', state, 0)).toThrow(
      "trying to switch to a state 'missing' that is undefined",
    );
  });

  test('rematches in the newly selected state', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [[/a/, { token: '@rematch', switchTo: 'other' }], [/./, 'unused']],
        other: [[/a/, 'letter'], [/./, 'other-character']],
      },
    });

    const result = tokenizer.tokenize('a', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'letter.runtime', value: 'a' },
    ]);
    expect(result.tokens.some((token) => token.type === '@rematch.runtime')).toBe(false);
  });

  test('goes back within the line and rematches the returned characters', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/ab/, { token: 'ab', goBack: 1 }],
          [/b/, 'b'],
          [/a/, 'a'],
        ],
      },
    });

    const result = tokenizer.tokenize('ab', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'ab.runtime', value: 'a' },
      { offset: 1, type: 'b.runtime', value: 'b' },
    ]);
  });
});

describe('MonarchTokenizer grouped actions', () => {
  test('emits one token per captured group and action', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [[/([a-z]+)(=)([0-9]+)/, ['name', 'operator', 'number']]],
      },
    });

    const result = tokenizer.tokenize('abc=12', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'name.runtime', value: 'abc' },
      { offset: 3, type: 'operator.runtime', value: '=' },
      { offset: 4, type: 'number.runtime', value: '12' },
    ]);
    expect(result.tokens.every((token) => token.stack.state === 'root')).toBe(true);
  });

  test.each([
    [
      'nested groups',
      { tokenizer: { root: [[/(a)(b)/, [['x', 'y'], 'z']]] } },
      'groups cannot be nested',
    ],
    [
      'too few actions',
      { tokenizer: { root: [[/(a)(b)/, ['x']]] } },
      'matched number of groups does not match the number of actions',
    ],
    [
      'non-consecutive captures',
      { tokenizer: { root: [[/(a)(?=(b))/, ['x', 'y']]] } },
      'with groups, all characters should be matched in consecutive groups',
    ],
  ])('rejects %s', (_label, language, message) => {
    const { tokenizer, state } = setup(language);
    expect(() => tokenizer.tokenize('ab', state, 0)).toThrow(message);
  });
});

describe('MonarchTokenizer case guards', () => {
  test('uses keyword lists with ignoreCase', () => {
    const { tokenizer, state } = setup({
      ignoreCase: true,
      keywords: ['if', 'else'],
      tokenizer: {
        root: [
          [/[a-z]+/, {
            cases: {
              '@keywords': 'keyword',
              '!@keywords': 'identifier',
            },
          }],
          [/[ \t]+/, ''],
        ],
      },
    });

    const result = tokenizer.tokenize('IF else nope', state, 0);

    expect(simpleTokens(result.tokens).map((token) => token.type)).toEqual([
      'keyword.runtime',
      '',
      'keyword.runtime',
      '',
      'identifier.runtime',
    ]);
  });

  test('supports regular-expression guards and a default branch', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/[a-z]+/, {
            cases: {
              '~fo+': 'keyword',
              '~bar|baz': 'keyword-two',
              '@default': 'identifier',
            },
          }],
          [/[ \t]+/, ''],
        ],
      },
    });

    const result = tokenizer.tokenize('foo bar qux', state, 0);

    expect(simpleTokens(result.tokens).map((token) => token.type)).toEqual([
      'keyword.runtime',
      '',
      'keyword-two.runtime',
      '',
      'identifier.runtime',
    ]);
  });

  test('guards on captures and the current state', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/([a-z]+):([a-z]+)/, {
            cases: {
              '$2if': 'keyword',
              '$S0root': 'state-word',
              '@default': 'identifier',
            },
          }],
          [/[ \t]+/, ''],
        ],
      },
    });

    const result = tokenizer.tokenize('x:if x:y', state, 0);

    expect(simpleTokens(result.tokens).map((token) => token.type)).toEqual([
      'keyword.runtime',
      '',
      'state-word.runtime',
    ]);
  });

  test('uses the end-of-stream guard for the final token only', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [
          [/[a-z]+/, {
            cases: {
              '@eos': 'end',
              '@default': 'identifier',
            },
          }],
          [/[ \t]+/, ''],
        ],
      },
    });

    const result = tokenizer.tokenize('done now', state, 0);

    expect(simpleTokens(result.tokens).map((token) => token.type)).toEqual([
      'identifier.runtime',
      '',
      'end.runtime',
    ]);
  });
});

describe('MonarchTokenizer action details', () => {
  test('substitutes captures, the full match, and the current state into token types', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [[/([a-z]+)([0-9]+)/, { token: 'kind.$1.$#.$0.$S0' }]],
      },
    });

    const result = tokenizer.tokenize('abc12', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'kind.abc.abc12.abc12.root.runtime', value: 'abc12' },
    ]);
  });

  test('emits mark tokens before the rule token', () => {
    const { tokenizer, state } = setup({
      tokenizer: {
        root: [[/[a-z]+/, { token: 'word', mark: 'marker' }]],
      },
    });

    const result = tokenizer.tokenize('abc', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'marker', value: null },
      { offset: 0, type: 'word.runtime', value: 'abc' },
    ]);
    expect(result.tokens[0].stack).toBe(null);
    expect(result.tokens[1].stack.state).toBe('root');
  });

  test('resolves @brackets against custom bracket definitions', () => {
    const { tokenizer, state } = setup({
      brackets: [['<', '>', 'tag.bracket']],
      tokenizer: {
        root: [
          [/[<>]/, '@brackets'],
          [/[a-z]+/, 'word'],
        ],
      },
    });

    const result = tokenizer.tokenize('<x>', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'tag.bracket.runtime', value: '<' },
      { offset: 1, type: 'word.runtime', value: 'x' },
      { offset: 2, type: 'tag.bracket.runtime', value: '>' },
    ]);
  });

  test('rejects @brackets when the matched bracket is not defined', () => {
    const { tokenizer, state } = setup({
      brackets: [],
      tokenizer: { root: [[/[<>]/, '@brackets']] },
    });

    expect(() => tokenizer.tokenize('<', state, 0)).toThrow(
      '@brackets token returned but no bracket defined as: <',
    );
  });

  test('sanitizes unsafe characters in emitted token classes', () => {
    const { tokenizer, state } = setup({
      tokenizer: { root: [[/x/, "a&<>\"'_"]] },
    });

    const result = tokenizer.tokenize('x', state, 0);

    expect(result.tokens[0].type).toBe('a------.runtime');
  });
});

describe('MonarchTokenizer includes and failure handling', () => {
  test('tokenizes with included rules from another state', () => {
    const { tokenizer, state } = setup({
      start: 'root',
      tokenizer: {
        base: [
          [/\d+/, 'number'],
          [/[ \t]+/, ''],
        ],
        root: [
          { include: '@base' },
          [/[a-z]+/, 'word'],
        ],
      },
    });

    const result = tokenizer.tokenize('12 abc', state, 0);

    expect(simpleTokens(result.tokens)).toEqual([
      { offset: 0, type: 'number.runtime', value: '12' },
      { offset: 2, type: '', value: ' ' },
      { offset: 3, type: 'word.runtime', value: 'abc' },
    ]);
  });

  test('reports a zero-length match that does not advance or change state', () => {
    const { tokenizer, state } = setup({
      tokenizer: { root: [[/a*/, 'word']] },
    });

    expect(() => tokenizer.tokenize('b', state, 0)).toThrow(
      'no progress in tokenizer',
    );
  });
});
