'use strict';

const { loadProduction } = require('./support/test-node');
const { Reporter } = loadProduction('reporter.js');

describe('Reporter', () => {
  test('initializes default reporter state', () => {
    const reporter = new Reporter();
    expect(reporter._reporterState).toEqual({
      obj: null,
      path: [],
      options: {},
      errors: [],
    });
  });

  test('keeps the supplied options object', () => {
    const options = { partial: true };
    const reporter = new Reporter(options);
    expect(reporter._reporterState.options).toBe(options);
    expect(reporter._reporterState.errors).toEqual([]);
  });

  test('tracks and truncates the reported path', () => {
    const reporter = new Reporter();
    expect(reporter.path()).toBe('');

    expect(reporter.enterKey('outer')).toBe(1);
    expect(reporter.enterKey(2)).toBe(2);
    expect(reporter.path()).toBe('outer/2');

    reporter.exitKey(2);
    expect(reporter.path()).toBe('outer');

    reporter.exitKey(1);
    expect(reporter.path()).toBe('');
  });

  test('leaveKey exits the path and writes into the current object', () => {
    const reporter = new Reporter();
    reporter.enterObject();
    const depth = reporter.enterKey('answer');

    reporter.leaveKey(depth, 'answer', 42);

    expect(reporter.path()).toBe('');
    expect(reporter._reporterState.obj).toEqual({ answer: 42 });
    expect(reporter.leaveObject(null)).toEqual({ answer: 42 });
  });

  test('leaveKey does not write when there is no current object', () => {
    const reporter = new Reporter();
    const depth = reporter.enterKey('answer');

    expect(() => reporter.leaveKey(depth, 'answer', 42)).not.toThrow();
    expect(reporter.path()).toBe('');
    expect(reporter._reporterState.obj).toBeNull();
  });

  test('enters and leaves objects as a stack', () => {
    const reporter = new Reporter();
    const root = reporter.enterObject();
    const first = reporter._reporterState.obj;
    const previous = reporter.enterObject();
    const second = reporter._reporterState.obj;

    expect(root).toBeNull();
    expect(previous).toBe(first);
    expect(second).not.toBe(first);
    expect(reporter.leaveObject(previous)).toBe(second);
    expect(reporter._reporterState.obj).toBe(first);
    expect(reporter.leaveObject(root)).toBe(first);
    expect(reporter._reporterState.obj).toBeNull();
  });

  test('saves and restores the current object and path depth', () => {
    const reporter = new Reporter();
    reporter.enterObject();
    const savedObject = reporter._reporterState.obj;
    reporter.enterKey('one');
    const saved = reporter.save();
    expect(saved).toEqual({ obj: savedObject, pathLen: 1 });

    reporter.enterKey('two');
    reporter.enterObject();
    reporter.restore(saved);

    expect(reporter._reporterState.obj).toBe(savedObject);
    expect(reporter.path()).toBe('one');
  });

  test('throws a path-aware ReporterError outside partial mode', () => {
    const reporter = new Reporter();
    reporter.enterKey('outer');
    reporter.enterKey('inner');

    let caught;
    try {
      reporter.error('boom');
    } catch (error) {
      caught = error;
    }

    expect(caught).toBeInstanceOf(Error);
    expect(caught.path).toBe('["outer"]["inner"]');
    expect(caught.message).toBe('boom at: ["outer"]["inner"]');
    expect(reporter.isError(caught)).toBe(true);
    expect(reporter.isError(new Error('plain'))).toBe(false);
    expect(reporter._reporterState.errors).toEqual([]);
  });

  test('uses the message of Error arguments and labels shallow paths', () => {
    const reporter = new Reporter();
    const source = new Error('inner failure');

    expect(() => reporter.error(source)).toThrow('inner failure at: (shallow)');
    expect(reporter._reporterState.errors).toEqual([]);
  });

  test('collects errors in partial mode instead of throwing', () => {
    const reporter = new Reporter({ partial: true });

    const first = reporter.error('first');
    const second = reporter.error('second');

    expect(reporter.isError(first)).toBe(true);
    expect(reporter.isError(second)).toBe(true);
    expect(reporter._reporterState.errors).toEqual([first, second]);
    expect(first.message).toBe('first at: (shallow)');
  });

  test('rethrows an existing ReporterError unchanged in any mode', () => {
    const partial = new Reporter({ partial: true });
    const existing = partial.error('once');

    expect(partial.error(existing)).toBe(existing);
    expect(partial._reporterState.errors).toEqual([existing]);

    const strict = new Reporter();
    expect(() => strict.error(existing)).toThrow(existing);
  });

  test('wraps results only in partial mode', () => {
    const strict = new Reporter();
    const value = { ok: true };
    expect(strict.wrapResult(value)).toBe(value);

    const partial = new Reporter({ partial: true });
    expect(partial.wrapResult(value)).toEqual({ result: value, errors: [] });

    const error = partial.error('bad input');
    expect(partial.wrapResult(error)).toEqual({
      result: null,
      errors: [error],
    });
    expect(partial.wrapResult(value).errors).toBe(partial._reporterState.errors);
  });
});
