const { DecoderBuffer, EncoderBuffer } = loadProduction('buffer.js');
const { Reporter } = loadProduction('reporter.js');

describe('DecoderBuffer', () => {
  test('wraps a Buffer and starts at offset zero', () => {
    const base = Buffer.from([0xde, 0xad, 0xbe, 0xef]);
    const decoder = new DecoderBuffer(base);

    expect(decoder).toBeInstanceOf(Reporter);
    expect(decoder.base).toBe(base);
    expect(decoder.offset).toBe(0);
    expect(decoder.length).toBe(4);
    expect(decoder.isEmpty()).toBe(false);
  });

  test('rejects non-Buffer input through the reporter', () => {
    expect(() => new DecoderBuffer('not a buffer')).toThrow('Input not Buffer at: (shallow)');
    expect(() => new DecoderBuffer([1, 2, 3])).toThrow('Input not Buffer');
  });

  test('records invalid input in partial mode and leaves data unset', () => {
    const decoder = new DecoderBuffer({ nope: true }, { partial: true });

    expect(decoder.base).toBeUndefined();
    expect(decoder.offset).toBeUndefined();
    expect(decoder.length).toBeUndefined();
    expect(decoder._reporterState.errors).toHaveLength(1);
    expect(decoder._reporterState.errors[0].message).toBe(
      'Input not Buffer at: (shallow)'
    );
  });

  test('treats an empty Buffer as empty', () => {
    expect(new DecoderBuffer(Buffer.alloc(0)).isEmpty()).toBe(true);
  });

  test('reads bytes and advances the offset', () => {
    const decoder = new DecoderBuffer(Buffer.from([1, 2, 3]));

    expect(decoder.readUInt8()).toBe(1);
    expect(decoder.offset).toBe(1);
    expect(decoder.readUInt8()).toBe(2);
    expect(decoder.readUInt8()).toBe(3);
    expect(decoder.offset).toBe(3);
    expect(decoder.isEmpty()).toBe(true);
  });

  test('reports an overrun with a default or custom message', () => {
    const decoder = new DecoderBuffer(Buffer.alloc(0));

    expect(() => decoder.readUInt8()).toThrow('DecoderBuffer overrun at: (shallow)');
    expect(() => decoder.readUInt8('custom overrun')).toThrow(
      'custom overrun at: (shallow)'
    );
  });

  test('skips a range and returns a shared-reporter view', () => {
    const base = Buffer.from([10, 20, 30, 40]);
    const decoder = new DecoderBuffer(base, { partial: true });
    const view = decoder.skip(2);

    expect(view).toBeInstanceOf(DecoderBuffer);
    expect(view.base).toBe(base);
    expect(view.offset).toBe(0);
    expect(view.length).toBe(2);
    expect(decoder.offset).toBe(2);
    expect(view._reporterState).toBe(decoder._reporterState);
    expect(view.readUInt8()).toBe(10);
    expect(decoder.readUInt8()).toBe(30);
  });

  test('reports a skip overrun without moving the offset', () => {
    const base = Buffer.from([1, 2]);
    const decoder = new DecoderBuffer(base, { partial: true });
    const result = decoder.skip(5);

    expect(decoder.isError(result)).toBe(true);
    expect(decoder.offset).toBe(0);
    expect(decoder._reporterState.errors).toHaveLength(1);
    expect(decoder._reporterState.errors[0].message).toMatch(
      /DecoderBuffer overrun/
    );
  });

  test('returns the remaining bytes from raw()', () => {
    const base = Buffer.from([1, 2, 3, 4]);
    const decoder = new DecoderBuffer(base);
    decoder.skip(2);

    expect(decoder.raw()).toEqual(base.slice(2));
    expect(decoder.raw()).not.toBe(base);
  });

  test('raw(save) returns the bytes consumed since the save point', () => {
    const base = Buffer.from([1, 2, 3, 4]);
    const decoder = new DecoderBuffer(base);
    const save = decoder.save();
    decoder.skip(3);

    expect(decoder.raw(save)).toEqual(base.slice(0, 3));
  });

  test('save/restore rewinds and returns the skipped bytes', () => {
    const base = Buffer.from([1, 2, 3, 4]);
    const decoder = new DecoderBuffer(base);
    decoder.readUInt8();
    const save = decoder.save();

    decoder.skip(2);
    const skipped = decoder.restore(save);

    expect(decoder.offset).toBe(1);
    expect(skipped.offset).toBe(1);
    expect(skipped.length).toBe(3);
    expect(skipped.base).toBe(base);
    expect(skipped.raw()).toEqual(base.slice(1, 3));
  });

  test('save/restore also rewinds the reporter path state', () => {
    const reporter = new Reporter();
    reporter.enterKey('outer');
    const save = reporter.save();
    reporter.enterKey('inner');

    reporter.restore(save);
    expect(reporter.path()).toBe('outer');
  });

  test('isDecoderBuffer accepts instances and compatible objects', () => {
    expect(DecoderBuffer.isDecoderBuffer(new DecoderBuffer(Buffer.alloc(1)))).toBe(
      true
    );

    const compatible = {
      base: Buffer.from([1]),
      offset: 0,
      length: 1,
      save() {},
      restore() {},
      isEmpty() {},
      readUInt8() {},
      skip() {},
      raw() {},
    };
    compatible.constructor = function DecoderBuffer() {};
    expect(DecoderBuffer.isDecoderBuffer(compatible)).toBe(true);
  });

  test('isDecoderBuffer rejects incompatible objects and Buffers', () => {
    expect(DecoderBuffer.isDecoderBuffer(Buffer.from([1]))).toBe(false);
    expect(DecoderBuffer.isDecoderBuffer({})).toBe(false);
    expect(
      DecoderBuffer.isDecoderBuffer({
        base: Buffer.from([1]),
        offset: 0,
        length: 1,
        constructor: function DecoderBuffer() {},
        save() {},
        restore() {},
        isEmpty() {},
        readUInt8() {},
        skip() {},
        // raw intentionally missing
      })
    ).toBe(false);
  });
});

describe('EncoderBuffer', () => {
  test('encodes a single byte number', () => {
    const encoder = new EncoderBuffer(0x2a);
    expect(encoder.value).toBe(0x2a);
    expect(encoder.length).toBe(1);
