    expect(output).toHaveLength(4);
    expect(output).toEqual(Buffer.from([1, 0x62, 0x63, 4]));
  });

  test('join() writes into a provided buffer at the requested offset', () => {
    const output = Buffer.alloc(6, 0xee);
