  test('empty arrays produce an empty buffer', () => {
    const encoder = new EncoderBuffer([]);
    expect(encoder.length).toBe(0);
    expect(encoder.value).toEqual([]);
    expect(encoder.join()).toEqual(Buffer.alloc(0));
  });

  test('rejects unsupported values through the reporter', () => {
    expect(() => new EncoderBuffer(undefined, new Reporter())).toThrow(
      'Unsupported type: undefined'
    );
    expect(() => new EncoderBuffer(null, new Reporter())).toThrow(
      'Unsupported type: object'
    );
    expect(() => new EncoderBuffer({}, new Reporter())).toThrow(
