    expect(clone).toBeInstanceOf(original.constructor);
    expect(clone._baseState.tag).toBe('int');
    expect(clone._baseState.optional).toBe(true);
    expect(clone._baseState.parent).toBe(original._baseState.parent);

    clone.implicit(9);
