'use strict';

const {
  loadProduction,
  TestNode,
  makeEntity,
} = require('./support/test-node');
const { DecoderBuffer, EncoderBuffer } = loadProduction('buffer.js');
const { Reporter } = loadProduction('reporter.js');

function tree(body) {
  const root = new TestNode();
  root._init(body);
  return root;
}

function encode(node, value) {
  const encoded = node._encode(value, new Reporter());
  return encoded instanceof EncoderBuffer ? encoded.join() : encoded;
}

function decode(node, buffer, options) {
  return node._decode(new DecoderBuffer(buffer, options));
}

describe('Node encoding and decoding', () => {
  test('round-trips a nested sequence of keyed primitives', () => {
    const node = tree(function () {
      this.seq().obj(
        this.key('id').int(),
        this.key('name').utf8str(),
        this.key('enabled').bool(),
        this.key('missing').null_()
      );
    });

    const value = { id: 42, name: 'imba', enabled: true, missing: null };
    const encoded = encode(node, value);

    expect(encoded).toBeInstanceOf(Buffer);
    expect(encoded[0]).toBe(0x30);
    expect(decode(node, encoded)).toEqual(value);
  });

  test('omits an absent optional child without a default', () => {
    const node = tree(function () {
      this.seq().obj(
        this.key('a').int(),
        this.key('b').optional().bool()
      );
    });

    expect(encode(node, { a: 1 })).toEqual(Buffer.from([0x30, 0x02, 0x02, 0x04].concat([])));
  });

  test('reads an empty optional body as an object without the key', () => {
    const node = tree(function () {
      this.seq().obj(
        this.key('a').int(),
        this.key('b').optional().bool()
      );
    });

    expect(decode(node, Buffer.from([0x30, 0x00]))).toEqual({});
  });

  test('substitutes a default for missing data and during decode', () => {
    const node = tree(function () {
      this.seq().obj(this.key('retries').int().def(7));
    });

    const encoded = encode(node, {});
    expect(decode(node, encoded)).toEqual({ retries: 7 });
    expect(decode(node, Buffer.from([0x30, 0x00]))).toEqual({ retries: 7 });
  });

  test('round-trips enum values through both argument maps', () => {
    const node = tree(function () {
      this.seq().obj(
        this.key('kind').enum({ 1: 'one', 2: 'two' })
      );
    });

    expect(decode(node, encode(node, { kind: 'two' }))).toEqual({ kind: 'two' });
  });

  test('applies implicit tags instead of the universal tag', () => {
    const node = tree(function () {
      this.seq().obj(this.key('value').implicit(0x80).int());
    });

    const encoded = encode(node, { value: 5 });
    expect(Array.from(encoded.slice(0, 4))).toEqual([0x30, 0x06, 0x80, 0x04]);
    expect(decode(node, encoded)).toEqual({ value: 5 });
  });

  test('wraps explicit tags around the normal encoding', () => {
    const node = tree(function () {
      this.seq().obj(this.key('value').explicit(0x80).int());
    });

    const encoded = encode(node, { value: 5 });
    expect(Array.from(encoded.slice(0, 6))).toEqual([0x30, 0x08, 0x80, 0x06, 0x02, 0x04]);
    expect(decode(node, encoded)).toEqual({ value: 5 });
  });

  test('round-trips a seqof list built from an entity', () => {
    const items = makeEntity(function () {
      this.int();
    });
    const node = tree(function () {
      this.seqof(items);
    });

    const encoded = encode(node, [1, 2, 3]);
    expect(encoded[0]).toBe(0x30);
    expect(decode(node, encoded)).toEqual([1, 2, 3]);
  });

  test('round-trips a setof list built from an entity', () => {
    const items = makeEntity(function () {
      this.utf8str();
    });
    const node = tree(function () {
      this.setof(items);
    });

    const encoded = encode(node, ['a', 'bc']);
    expect(encoded[0]).toBe(0x31);
    expect(decode(node, encoded)).toEqual(['a', 'bc']);
  });

  test('reports seqof misuse: missing schema and non-array data', () => {
    const missingSchema = tree(function () {
      this.seqof();
    });
    expect(() => encode(missingSchema, [1])).toThrow(
      'Too many args for : seqof'
    );

    const items = makeEntity(function () {
      this.int();
    });
    const node = tree(function () {
      this.seqof(items);
    });
    expect(() => encode(node, 'not-an-array')).toThrow(
      'seqof/setof, but data is not Array'
    );
  });

  test('encodes and decodes arbitrary TLV data with any()', () => {
    const node = tree(function () {
      this.seq().obj(this.key('raw').any());
    });
    const raw = Buffer.from([0x04, 0x02, 0x41, 0x42]);

    const encoded = encode(node, { raw });
    expect(encoded).toEqual(Buffer.from([0x30, 0x04, 0x04, 0x02, 0x41, 0x42]));
    expect(decode(node, encoded)).toEqual({ raw });
  });

  test('selects and decodes the matching choice alternative', () => {
    const node = tree(function () {
      this.seq().obj(
        this.key('value').choice({
          number: this.int(),
          text: this.utf8str(),
        })
      );
    });

    const numberEncoded = encode(node, { value: { type: 'number', value: 9 } });
