'use strict';

const {
  loadProduction,
  TestNode,
  Node,
} = require('./support/test-node');

const index = loadProduction('index.js');
const { Reporter } = loadProduction('reporter.js');
const { DecoderBuffer, EncoderBuffer } = loadProduction('buffer.js');

describe('asn1 base index', () => {
  test('re-exports every public base constructor', () => {
    expect(index.Reporter).toBe(Reporter);
    expect(index.DecoderBuffer).toBe(DecoderBuffer);
    expect(index.EncoderBuffer).toBe(EncoderBuffer);
    expect(index.Node.default).toBe(Node);
  });

  test('contains a usable Node constructor', () => {
    const BaseNode = index.Node.default;
    const root = new BaseNode('der');

    expect(root).toBeInstanceOf(BaseNode);
    expect(root._baseState.enc).toBe('der');
    expect(root._baseState.children).toEqual([]);
  });

  test('works with index-provided collaboration between buffers, reporter, and nodes', () => {
    const root = new TestNode();
    root._init(function () {
      this.seq().obj(
        this.key('id').int(),
        this.key('label').optional().utf8str()
      );
    });

    const reporter = new index.Reporter();
    const encodedBuffer = root._encode({ id: 17, label: 'seventeen' }, reporter);

    expect(encodedBuffer).toBeInstanceOf(index.EncoderBuffer);
    const encoded = encodedBuffer.join();
    expect(encoded).toBeInstanceOf(Buffer);

    const decoded = root._decode(new index.DecoderBuffer(encoded));
    expect(decoded).toEqual({ id: 17, label: 'seventeen' });

    const partial = root._decode(
      new index.DecoderBuffer(Buffer.from([0x30]), { partial: true }),
      { partial: true }
    );
    expect(partial.result).toBeNull();
    expect(partial.errors.length).toBeGreaterThan(0);
  });

  test('exposes the same Reporter class used by DecoderBuffer', () => {
    const decoder = new index.DecoderBuffer(Buffer.from([1]));

    expect(decoder).toBeInstanceOf(index.Reporter);
    expect(decoder._reporterState.options).toEqual({});
  });
});
