    format: 'cjs',
    loader: 'js',
    target: 'node20',
    sourcefile: resolved,
  });

  const module = { exports: {} };
  moduleCache.set(resolved, module);

  const dirname = path.dirname(resolved);
  const localRequire = (request) => {
    if (request.startsWith('.') || path.isAbsolute(request)) {
