describe('toArrayBuffer', () => {
  const toArrayBuffer = require('../../../../../packages/imba/polyfills/http/http-lib/to-arraybuffer').default;

  test('returns the underlying ArrayBuffer for a full Uint8Array view', () => {
    const view = new Uint8Array([1, 2, 3, 4]);

    const result = toArrayBuffer(view);

    expect(result).toBe(view.buffer);
    expect(Array.from(new Uint8Array(result))).toEqual([1, 2, 3, 4]);
  });

  test('returns a correctly bounded copy for a Uint8Array subarray', () => {
    const original = new Uint8Array([9, 1, 2, 3, 8]);
    const view = original.subarray(1, 4);

    const result = toArrayBuffer(view);

    expect(result).not.toBe(original.buffer);
    expect(Array.from(new Uint8Array(result))).toEqual([1, 2, 3]);
  });

  test('copies exactly the bytes of a Node Buffer', () => {
    const buffer = Buffer.from([10, 20, 30, 40, 50]);

    const result = toArrayBuffer(buffer);

    expect(result.byteLength).toBe(buffer.length);
    expect(Array.from(new Uint8Array(result))).toEqual([10, 20, 30, 40, 50]);
  });

  test('falls back to byte-by-byte copying for Buffer implementations that are not Uint8Arrays', () => {
    const originalUint8Array = global.Uint8Array;
    function CompatibleUint8Array(length) {
      return new originalUint8Array(length);
    }
    try {
      global.Uint8Array = CompatibleUint8Array;
      const result = toArrayBuffer(Buffer.from([7, 8, 9]));
      expect(Array.from(new originalUint8Array(result))).toEqual([7, 8, 9]);
    } finally {
      global.Uint8Array = originalUint8Array;
    }
  });

  test('rejects values that are neither Uint8Array views nor Buffers', () => {
    expect(() => toArrayBuffer('not a buffer')).toThrow('Argument must be a Buffer');
    expect(() => toArrayBuffer([1, 2, 3])).toThrow('Argument must be a Buffer');
    expect(() => toArrayBuffer(null)).toThrow('Argument must be a Buffer');
  });
});
