const h = require('./test-utils.cjs');
const {Writable} = require('stream');

describe('http ClientRequest', () => {
  beforeEach(() => {
    h.preserveGlobals();
  });

  afterEach(() => {
    h.restoreGlobals();
  });

  function install({fetchEnabled = false, xhrOptions = {}} = {}) {
    h.setGlobal('location', {host: 'app.test', protocol: 'https:'});
    const fetchMock = jest.fn();
    h.setGlobal('fetch', fetchEnabled ? fetchMock : undefined);
    h.setGlobal('ReadableStream', fetchEnabled ? function ReadableStream() {} : undefined);
    const XHR = h.createFakeXHR(xhrOptions);
    h.setGlobal('XMLHttpRequest', XHR);
    jest.resetModules();
    const ClientRequest = h.load('http-lib/request').default;
    return {ClientRequest, XHR, fetchMock};
  }

  test('is a Writable and manages headers case-insensitively', () => {
    const {ClientRequest} = install();
    const req = new ClientRequest({headers: {}});

    expect(req).toBeInstanceOf(Writable);

    req.setHeader('X-Test', 'first');
    req.setHeader('x-test', 'second');
    expect(req.getHeader('X-TEST')).toBe('second');

    req.removeHeader('x-Test');
    expect(() => req.getHeader('X-Test')).toThrow();
  });

  test('adds basic auth and ignores unsafe request headers', () => {
    const {ClientRequest} = install();
    const req = new ClientRequest({
      auth: 'user:pa:ss',
      headers: {
        'X-Allowed': 'kept',
        Host: 'unsafe.example',
        Cookie: 'session=secret',
        'User-Agent': 'unsafe-agent'
      }
    });

    expect(req.getHeader('authorization')).toBe(
      'Basic ' + Buffer.from('user:pa:ss').toString('base64')
    );
    expect(req.getHeader('x-allowed')).toBe('kept');
    expect(() => req.getHeader('host')).toThrow();
    expect(() => req.getHeader('cookie')).toThrow();
    expect(() => req.getHeader('user-agent')).toThrow();
  });

  test('rejects an unknown request mode', () => {
    const {ClientRequest} = install();

    expect(() => new ClientRequest({headers: {}, mode: 'not-a-mode'})).toThrow(
      'Invalid value for opts.mode'
    );
  });

  test('uses fetch for the default mode and sends headers, credentials and a Blob body', async () => {
    const {ClientRequest, fetchMock} = install({fetchEnabled: true});
    const fetchResponse = h.createFetchResponse({status: 200, statusText: 'OK', chunks: ['ok']});
    fetchMock.mockResolvedValue(fetchResponse);

    const req = new ClientRequest({
      url: 'https://api.test/items',
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain',
        'X-Request-Id': 'abc'
      },
      withCredentials: true
    });
    const responsePromise = h.once(req, 'response');

    req.write('hello');
    req.end(' world');
    const response = await responsePromise;

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [url, init] = fetchMock.mock.calls[0];
    expect(url).toBe('https://api.test/items');
    expect(init.method).toBe('POST');
    expect(init.headers).toEqual([
      ['Content-Type', 'text/plain'],
      ['X-Request-Id', 'abc']
    ]);
    expect(init.mode).toBe('cors');
    expect(init.credentials).toBe('include');
    expect(init.body).toBeInstanceOf(Blob);
    expect(init.body.type).toBe('text/plain');
    expect(await init.body.text()).toBe('hello world');
    expect(response.statusCode).toBe(200);
  });

  test('uses same-origin fetch credentials by default for GET requests', async () => {
    const {ClientRequest, fetchMock} = install({fetchEnabled: true});
    fetchMock.mockResolvedValue(h.createFetchResponse({status: 204, statusText: 'No Content'}));

    const req = new ClientRequest({
      url: 'https://api.test/items',
      method: 'GET',
      headers: {}
    });
    const responsePromise = h.once(req, 'response');
    req.end();
    await responsePromise;

    const [, init] = fetchMock.mock.calls[0];
    expect(init.body).toBeUndefined();
    expect(init.credentials).toBe('same-origin');
  });

  test('emits fetch failures as request errors', async () => {
    const {ClientRequest, fetchMock} = install({fetchEnabled: true});
    const failure = new Error('network down');
    fetchMock.mockRejectedValue(failure);

    const req = new ClientRequest({
      url: 'https://api.test/failure',
      method: 'GET',
      headers: {}
    });
    const errorPromise = h.once(req, 'error');
    req.end();

    await expect(errorPromise).resolves.toBe(failure);
  });

  test('can disable fetch and use an arraybuffer XHR, falling back to string bodies', async () => {
    const {ClientRequest, XHR, fetchMock} = install({
      fetchEnabled: true,
      xhrOptions: {supportedResponseTypes: ['arraybuffer']}
    });
    h.setGlobal('Blob', class BrokenBlob {
      constructor() {
        throw new Error('Blob unavailable');
      }
    });

    const req = new ClientRequest({
      url: 'https://api.test/xhr-post',
      method: 'POST',
      headers: {'Content-Type': 'text/plain'},
      mode: 'disable-fetch'
    });
    req.write('hello');
    req.end(' world');
    await h.flushPromises();

    expect(fetchMock).not.toHaveBeenCalled();
    const xhr = XHR.instances.find((item) => item.opened && item.opened.url === 'https://api.test/xhr-post');
    expect(xhr).toBeDefined();
    expect(xhr.opened).toEqual({method: 'POST', url: 'https://api.test/xhr-post', async: true});
    expect(xhr.responseType).toBe('arraybuffer');
    expect(xhr.requestHeaders).toEqual({'Content-Type': 'text/plain'});
    expect(xhr.sentBody).toBe('hello world');
  });

  test('uses text mode with the legacy mime override for prefer-streaming requests', async () => {
    const {ClientRequest, XHR, fetchMock} = install({
      fetchEnabled: false,
      xhrOptions: {supportedResponseTypes: ['arraybuffer'], overrideMimeType: true}
    });

    const req = new ClientRequest({
      url: 'https://api.test/stream',
      method: 'GET',
      headers: {Accept: 'text/plain'},
      mode: 'prefer-streaming'
    });
    req.end();
    await h.flushPromises();

    const xhr = XHR.instances.find((item) => item.opened && item.opened.url === 'https://api.test/stream');
    expect(fetchMock).not.toHaveBeenCalled();
    expect(xhr.responseType).toBe('text');
    expect(xhr.overriddenMimeType).toBe('text/plain; charset=x-user-defined');
    expect(xhr.requestHeaders).toEqual({Accept: 'text/plain'});
  });

  test('chooses text mode for allow-wrong-content-type when mime overrides exist', async () => {
    const {ClientRequest, XHR} = install({
      xhrOptions: {supportedResponseTypes: ['arraybuffer'], overrideMimeType: true}
    });

    const req = new ClientRequest({
      url: 'https://api.test/allow-text',
      method: 'GET',
      headers: {},
      mode: 'allow-wrong-content-type'
    });
    req.end();
    await h.flushPromises();

    const xhr = XHR.instances.find((item) => item.opened && item.opened.url === 'https://api.test/allow-text');
    expect(xhr.responseType).toBe('text');
    expect(xhr.overriddenMimeType).toBe('text/plain; charset=x-user-defined');
  });

  test('chooses binary mode for allow-wrong-content-type without mime overrides', async () => {
    const {ClientRequest, XHR} = install({
      xhrOptions: {supportedResponseTypes: ['arraybuffer'], overrideMimeType: false}
    });

    const req = new ClientRequest({
      url: 'https://api.test/allow-binary',
      method: 'GET',
      headers: {},
