function isPrime(n){ if(n<2) return false; for(let i=2;i*i<=n;i++) if(n%i===0) return false; return true; }
function sqrtMod(a,p){ for(let y=0;y<p;y++) if((y*y)%p===a%p) return y; return null; }
function points(a,b,p){ const res=[]; for(let x=0;x<p;x++){ const rhs=(x*x*x+a*x+b)%p; const y=sqrtMod(((rhs%p)+p)%p,p); if(y!==null) res.push([x,y%p]); } return res; }
