const load = require('./loader');
const Ed = load('edwards.js').default;
const BN = load('../../../bn.js').default;
const p = 23n;
function mod(a,m){const r=a%m;return r<0n?r+m:r;}
function inv(a){let t=0n,nt=1n,r=p,nr=mod(a,p);while(nr){const q=r/nr;[t,nt]=[nt,t-q*nt];[r,nr]=[nr,r-q*nr];}return mod(t,p);}
function pts(a,c,d){const out=[];const c2=mod(c*c,p);for(let x=0n;x<p;x++)for(let y=0n;y<p;y++){const lhs=mod(a*x*x+y*y,p);const rhs=mod(c2*(1n+d*x*x*y*y),p);if(lhs===rhs)out.push([x,y]);}return out;}
