const p=23n;
const mod=(a,m=p)=>((a%m)+m)%m;
function inv(a){let t=0n,nt=1n,r=p,nr=mod(a);while(nr){const q=r/nr;[t,nt]=[nt,t-q*nt];[r,nr]=[nr,r-q*nr];}return mod(t);}
const isSq=v=>{for(let i=0n;i<p;i++)if(mod(i*i)===mod(v))return true;return false;};
function pts(a,c,d){const out=[];const c2=mod(c*c);for(let x=0n;x<p;x++)for(let y=0n;y<p;y++){if(mod(a*x*x+y*y)===mod(c2*(1n+d*x*x*y*y)))out.push([x,y]);}return out;}
function refAdd(P,Q,a,d){const [x1,y1]=P,[x2,y2]=Q;const t=mod(d*x1*x2*y1*y2);const x3=mod(mod(x1*y2+x2*y1)*inv(1n+t));const y3=mod(mod(y1*y2-a*x1*x2)*inv(1n-t));return [x3,y3];}
function refMul(P,k,a,d){let R=[0n,1n];for(let i=0;i<k;i++)R=refAdd(R,P,a,d);return R;}
for (const [a,d] of [[5n,5n],[1n,5n],[5n,3n]]) {
  const list=pts(a,1n,d);
  console.log('a',a,'d',d,'sq(a)',isSq(a),'sq(d)',isSq(d),'npoints',list.length);
  // find order of each point
  const orders = list.map(P=>{let R=[0n,1n];for(let k=1;k<=50;k++){R=refAdd(R,P,a,d);if(R[0]===0n&&R[1]===1n)return k;}return -1;});
  console.log(' orders', [...new Set(orders)].sort((x,y)=>x-y));
  const idx = orders.findIndex(o=>o>8);
  if(idx>=0) console.log(' candidate', list[idx].map(String), 'order', orders[idx]);
}
EOF
