 * Aggregator tests for `curve/index.js`, which glues the four concrete curve
 * implementations of this module together.
 */
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const PROD_DIR = (() => {
  const marker = path.sep + 'test' + path.sep;
  const repoRoot = __dirname.slice(0, __dirname.indexOf(marker));
  return path.join(
    repoRoot,
    'packages/imba/polyfills/crypto/esm/lib/elliptic/lib/curve'
  );
})();

const moduleCache = new Map();

function loadModule(filename) {
  const cached = moduleCache.get(filename);
  if (cached) return cached.exports;
  const mod = { exports: {} };
  moduleCache.set(filename, mod);
  const { code } = esbuild.transformSync(fs.readFileSync(filename, 'utf8'), {
    format: 'cjs',
    loader: 'js',
    sourcefile: filename,
  });
  const dir = path.dirname(filename);
  const localRequire = (request) => {
    if (!request.startsWith('.')) return require(request);
    let target = path.resolve(dir, request);
    if (!fs.existsSync(target) && fs.existsSync(target + '.js')) target += '.js';
    return loadModule(target);
  };
  new Function('exports', 'require', 'module', '__filename', '__dirname', code)(
    mod.exports,
    localRequire,
    mod,
    filename,
    dir
  );
  return mod.exports;
}

const load = (name) => loadModule(path.join(PROD_DIR, name));
const constructorOf = (loaded) =>
  typeof loaded === 'function' ? loaded : loaded && loaded.default;

const curve = load('index.js');

/** Minimal configurations that only rely on the module's own public API. */
const SHORT_CONF = {
  prime: 'k256',
  p: 'fffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2f',
  a: '0',
  b: '7',
  n: 'fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141',
  g: [
    '79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798',
    '483ada7726a3c4655da4fbfc0e1108a8fd17b448a68554199c47d08ffb10d4b8',
  ],
};
const MONT_CONF = {
  prime: 'p25519',
  p: '7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed',
  a: '76d06',
  b: '1',
  g: ['9'],
};
const EDWARDS_CONF = {
  prime: 'p25519',
  p: '7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed',
  a: '-1',
  c: '1',
  d: '52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3',
  n: '1000000000000000000000000000000014def9dea2f79cd65812631a5cf5d3ed',
  g: [
    '216936d3cd6e53fec0a4e231fdd6dc5c692cc7609525a7b2c9562d608f25d51a',
    '6666666666666666666666666666666666666666666666666666666666666658',
  ],
};

describe('curve/index.js', () => {
  test('exposes exactly the four curve implementations', () => {
    expect(Object.keys(curve)).toEqual(['base', 'short', 'mont', 'edwards']);
  });

  test('re-exports the very same modules as the individual entry points', () => {
    expect(curve.base).toBe(load('base.js'));
    expect(curve.short).toBe(load('short.js'));
    expect(curve.mont).toBe(load('mont.js'));
    expect(curve.edwards).toBe(load('edwards.js'));
  });

  test('every entry point is a constructor', () => {
    for (const name of Object.keys(curve)) {
      expect(typeof constructorOf(curve[name])).toBe('function');
    }
  });

  test('builds a working short curve', () => {
    const ShortCurve = constructorOf(curve.short);
    const short = new ShortCurve(SHORT_CONF);

    expect(short.type).toBe('short');
    expect(short.validate(short.g)).toBe(true);
    expect(short.g.mul(short.n).isInfinity()).toBe(true);
  });

  test('builds a working Montgomery curve', () => {
    const MontCurve = constructorOf(curve.mont);
    const mont = new MontCurve(MONT_CONF);

    expect(mont.type).toBe('mont');
    expect(mont.g.getX().toString(16)).toBe('9');
  });

  test('builds a working Edwards curve', () => {
    const EdwardsCurve = constructorOf(curve.edwards);
    const edwards = new EdwardsCurve(EDWARDS_CONF);

    expect(edwards.type).toBe('edwards');
    expect(edwards.validate(edwards.g)).toBe(true);
    expect(edwards.g.mul(edwards.n).isInfinity()).toBe(true);
  });

  test('short curves built through the index use the base implementation', () => {
    const BaseCurve = constructorOf(curve.base);
    const ShortCurve = constructorOf(curve.short);
    const short = new ShortCurve(SHORT_CONF);

    expect(short).toBeInstanceOf(BaseCurve);
  });
});
