const load = require('./loader');
const Short = load('short.js').default;
const BN = load('../../../bn.js').default;
const SECP = {prime:'k256',p:'fffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2f',a:'0',b:'7',n:'fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141',g:['79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798','483ada7726a3c4655da4fbfc0e1108a8fd17b448a68554199c47d08ffb10d4b8']};
const c = new Short(SECP);
const G = c.g;
console.log('mul n+5 == mul 5', G.mul(c.n.addn(5)).eq(G.mul(5)));
console.log('naf4 len', G._getNAFPoints(4).points.length);
console.log('naf4 15th', G._getNAFPoints(4).points[14].eq(G.mul(29)));
// smallest non-residue x for y^2 = x^3+7
const p = c.p;
let found = null;
for (let x = 0; x < 50; x++) {
  const xb = new BN(x);
  const rhs = xb.toRed(c.red).redSqr().redMul(xb).redIAdd(xb.toRed(c.red).redMul(c.a)).redIAdd(c.b);
  if (rhs.fromRed().pow(p.subn(1).divn(2), p).cmpn(1) !== 0) { found = x; break; }
}
console.log('smallest non-residue x', found);
try { c.pointFromX(new BN(found)); } catch(e) { console.log('throws', e.message); }
// endo split bounds
for (const k of ['1','ff','1234567890abcdef','fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364140']) {
  const kb = new BN(k,16);
  const s = c._endoSplit(kb);
  console.log('split', k.slice(0,8), 'ok', s.k1.add(s.k2.mul(c.endo.lambda)).umod(c.n).cmp(kb.umod(c.n))===0, 'bits', s.k1.bitLength(), s.k2.bitLength(), s.k1.negative, s.k2.negative);
}
// hasDoubles boundary
G.precompute(8);
console.log('doubles len', G.precomputed.doubles.points.length);
for (const bits of [8, 11, 12, 13]) {
  const k = new BN(1).ushln(bits-1);  // bitLength = bits
  console.log('bits', bits, 'has', G._hasDoubles(k));
}
console.log('precompute idempotent', G.precompute(8) === G, Object.keys(G.precomputed));
