/**
 * Behavioural tests for the short Weierstrass curve implementation.
 *
 * Scalar multiplication, doubling and point encoding are verified against an
 * independent (BigInt, affine) reference implementation of the same curve so
 * that the expectations are not derived from the production algorithms.
 */
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const PROD_DIR = (() => {
  const marker = path.sep + 'test' + path.sep;
  const repoRoot = __dirname.slice(0, __dirname.indexOf(marker));
  return path.join(
    repoRoot,
    'packages/imba/polyfills/crypto/esm/lib/elliptic/lib/curve'
  );
})();

const moduleCache = new Map();

function loadModule(filename) {
  const cached = moduleCache.get(filename);
  if (cached) return cached.exports;
  const mod = { exports: {} };
  moduleCache.set(filename, mod);
  const { code } = esbuild.transformSync(fs.readFileSync(filename, 'utf8'), {
    format: 'cjs',
    loader: 'js',
    sourcefile: filename,
  });
  const dir = path.dirname(filename);
  const localRequire = (request) => {
    if (!request.startsWith('.')) return require(request);
    let target = path.resolve(dir, request);
    if (!fs.existsSync(target) && fs.existsSync(target + '.js')) target += '.js';
    return loadModule(target);
  };
  new Function('exports', 'require', 'module', '__filename', '__dirname', code)(
    mod.exports,
    localRequire,
    mod,
    filename,
    dir
  );
  return mod.exports;
}

const loadDefault = (name) => {
  const loaded = loadModule(path.join(PROD_DIR, name));
  return loaded && loaded.default ? loaded.default : loaded;
};

const ShortCurve = loadDefault('short.js');
const BaseCurve = loadDefault('base.js');
const BN = loadDefault('../../../bn.js');

const K256_P =
  'fffffffffffffffffffffffffffffffffffffffffffffffffffffffefffffc2f';
const K256_N =
  'fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141';

/** secp256k1 with the pre-computed endomorphism parameters supplied. */
const SECP256K1 = {
  prime: 'k256',
  p: K256_P,
  a: '0',
  b: '7',
  n: K256_N,
  beta: '7ae96a2b657c07106e64479eac3434e99cf0497512f58995c1396c28719501ee',
  lambda: '5363ad4cc05c30e0a5261c028812645a122e22ea20816678df02967c1b23bd72',
  basis: [
    {
      a: '3086d221a7d46bcde86c90e49284eb15',
      b: '-e4437ed6010e88286f547fa90abfe4c3',
    },
    {
      a: '114ca50f7a8e2f3f657c1108d9d44cfd8',
      b: '3086d221a7d46bcde86c90e49284eb15',
    },
  ],
  g: [
    '79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798',
    '483ada7726a3c4655da4fbfc0e1108a8fd17b448a68554199c47d08ffb10d4b8',
  ],
};

/** NIST P-256: the a = -3 branch of the doubling code. */
const P256 = {
  p: 'ffffffff00000001000000000000000000000000ffffffffffffffffffffffff',
  a: 'ffffffff00000001000000000000000000000000fffffffffffffffffffffffc',
  b: '5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b',
  n: 'ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551',
  g: [
    '6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296',
    '4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5',
  ],
};

/** Tiny curve over GF(23) with a = 5, b = 7: exercises the generic doubling path. */
const SMALL = { p: '17', a: '5', b: '7', g: ['1', '6'] };

const P_BIG = BigInt('0x' + K256_P);
const A_BIG = 0n;
const B_BIG = 7n;
const GX_BIG = BigInt('0x' + SECP256K1.g[0]);
const GY_BIG = BigInt('0x' + SECP256K1.g[1]);

const mod = (value, m = P_BIG) => ((value % m) + m) % m;

function inverse(value, m = P_BIG) {
  let [oldR, r] = [mod(value, m), m];
  let [oldS, s] = [1n, 0n];
  while (r !== 0n) {
    const q = oldR / r;
    [oldR, r] = [r, oldR - q * r];
    [oldS, s] = [s, oldS - q * s];
  }
  return mod(oldS, m);
}

/** Affine point addition on secp256k1; `[null, null]` is the point at infinity. */
function refAdd(first, second) {
  const [x1, y1] = first;
  const [x2, y2] = second;
  if (x1 === null) return second;
  if (x2 === null) return first;
  if (x1 === x2 && mod(y1 + y2) === 0n) return [null, null];
  const slope =
    x1 === x2 && y1 === y2
      ? mod(3n * x1 * x1 + A_BIG) * inverse(2n * y1) % P_BIG
      : mod(y2 - y1) * inverse(x2 - x1) % P_BIG;
  const x3 = mod(slope * slope - x1 - x2);
  const y3 = mod(slope * (x1 - x3) - y1);
  return [x3, y3];
}

function refMul(scalar) {
  let result = [null, null];
  let addend = [GX_BIG, GY_BIG];
  let remaining = scalar;
  while (remaining > 0n) {
    if (remaining & 1n) result = refAdd(result, addend);
    addend = refAdd(addend, addend);
    remaining >>= 1n;
  }
  return result;
}

const isOnCurve = (point) =>
  point[0] !== null &&
  mod(point[1] * point[1]) === mod(point[0] ** 3n + A_BIG * point[0] + B_BIG);

function expectMatchesReference(point, reference) {
  if (reference[0] === null) {
    expect(point.isInfinity()).toBe(true);
    return;
  }
  expect(point.isInfinity()).toBe(false);
  expect(point.getX().toString(16)).toBe(reference[0].toString(16));
  expect(point.getY().toString(16)).toBe(reference[1].toString(16));
}

describe('ShortCurve configuration', () => {
  test('derives the short curve flags for secp256k1', () => {
    const curve = new ShortCurve(SECP256K1);

    expect(curve).toBeInstanceOf(BaseCurve);
    expect(curve.type).toBe('short');
    expect(curve.a.fromRed().toString()).toBe('0');
    expect(curve.b.fromRed().toString()).toBe('7');
    expect(curve.zeroA).toBe(true);
    expect(curve.threeA).toBe(false);
  });

  test('derives the a = -3 flag for P-256', () => {
    const curve = new ShortCurve(P256);

    expect(curve.zeroA).toBe(false);
    expect(curve.threeA).toBe(true);
    expect(curve.a.fromRed().cmp(curve.p.subn(3))).toBe(0);
  });

  test('precomputes the inverse of two used by the doubling formulas', () => {
    const curve = new ShortCurve(P256);

    expect(curve.tinv.redMul(curve.two).fromRed().cmpn(1)).toBe(0);
  });

  test('uses the endomorphism parameters from the configuration', () => {
    const curve = new ShortCurve(SECP256K1);

    expect(curve.endo.beta.fromRed().toString(16)).toBe(SECP256K1.beta);
    expect(curve.endo.lambda.toString(16)).toBe(SECP256K1.lambda);
    expect(curve.endo.basis.map((v) => [v.a.toString(16), v.b.toString(16)])).toEqual([
      [SECP256K1.basis[0].a, SECP256K1.basis[0].b],
      [SECP256K1.basis[1].a, SECP256K1.basis[1].b],
    ]);
  });

  test('derives usable endomorphism parameters when they are not configured', () => {
    const { beta, lambda, basis, ...conf } = SECP256K1;
    const curve = new ShortCurve(conf);

    expect(curve.endo).toBeDefined();
    // lambda^2 + lambda + 1 == 0 (mod n) and beta^2 + beta + 1 == 0 (mod p)
    expect(
      curve.endo.lambda
        .sqr()
        .add(curve.endo.lambda)
        .addn(1)
        .umod(curve.n)
        .cmpn(0)
    ).toBe(0);
    expect(
      curve.endo.beta
        .fromRed()
        .sqr()
        .add(curve.endo.beta.fromRed())
        .addn(1)
        .umod(curve.p)
        .cmpn(0)
    ).toBe(0);
    // lambda * G == (beta * Gx, Gy)
    expect(
      curve.g
        .mul(curve.endo.lambda)
        .getX()
        .cmp(curve.g.x.redMul(curve.endo.beta).fromRed())
    ).toBe(0);
    // the basis vectors satisfy a + b * lambda == 0 (mod n)
    for (const vector of curve.endo.basis) {
      expect(vector.a.add(vector.b.mul(curve.endo.lambda)).umod(curve.n).cmpn(0)).toBe(0);
    }
  });

  test('skips the endomorphism when a is non-zero', () => {
    const curve = new ShortCurve(SMALL);

    expect(curve.endo).toBeUndefined();
  });

  test('skips the endomorphism when the field prime is 2 mod 3', () => {
    const curve = new ShortCurve({ p: '17', a: '0', b: '7', n: 'b', g: ['1', '6'] });

    expect(curve.p.modn(3)).toBe(2);
    expect(curve.endo).toBeUndefined();
  });

  test('builds the generator from the configuration', () => {
    const curve = new ShortCurve(SECP256K1);

    expect(curve.g.type).toBe('affine');
    expect(curve.g.isInfinity()).toBe(false);
    expect(curve.g.getX().toString(16)).toBe(SECP256K1.g[0]);
    expect(curve.g.getY().toString(16)).toBe(SECP256K1.g[1]);
  });
});

describe('ShortCurve validation and point recovery', () => {
  const curve = new ShortCurve(SECP256K1);

  test('validate() accepts points on the curve', () => {
    expect(curve.validate(curve.g)).toBe(true);
    expect(curve.validate(curve.g.mul(12345))).toBe(true);
  });

  test('validate() accepts the point at infinity', () => {
    expect(curve.validate(curve.point(null, null))).toBe(true);
  });

  test('validate() rejects points that are not on the curve', () => {
    const offCurve = curve.point(curve.g.x, curve.g.y.redAdd(curve.one));

    expect(curve.validate(offCurve)).toBe(false);
  });

  test('pointFromX() recovers the point for the requested parity', () => {
    const odd = curve.g.getY().isOdd();

    expectMatchesReference(curve.pointFromX(curve.g.getX(), odd), [GX_BIG, GY_BIG]);
    expectMatchesReference(curve.pointFromX(curve.g.getX(), !odd), [
      GX_BIG,
      mod(-GY_BIG),
    ]);
  });

  test('pointFromX() rejects x values without a square root', () => {
    // x = 0 gives y^2 = 7 which is a quadratic non-residue modulo the field prime
    expect(() => curve.pointFromX(new BN(0))).toThrow('invalid point');
  });

  test('pointFromJSON() rebuilds points and generators', () => {
    const restored = curve.pointFromJSON(SECP256K1.g.slice());

    expectMatchesReference(restored, [GX_BIG, GY_BIG]);
  });
});

describe('ShortCurve affine arithmetic', () => {
  const curve = new ShortCurve(SECP256K1);
  const G = curve.g;
  const TWO_G = refMul(2n);
  const THREE_G = refMul(3n);

  test('exposes the point at infinity as the neutral element', () => {
    const infinity = curve.point(null, null);

    expect(infinity.isInfinity()).toBe(true);
    expect(infinity.add(G)).toBe(G);
    expect(G.add(infinity)).toBe(G);
    expect(infinity.dbl()).toBe(infinity);
  });

  test('doubling matches an independent affine implementation', () => {
    expectMatchesReference(G.dbl(), TWO_G);
    expect(isOnCurve(TWO_G)).toBe(true);
  });

  test('addition matches an independent affine implementation', () => {
    expectMatchesReference(G.add(G.dbl()), THREE_G);
    expectMatchesReference(G.dbl().add(G), THREE_G);
  });

  test('addition is commutative and associative', () => {
    const P = G.mul(7);
    const Q = G.mul(11);
    const R = G.mul(13);

    expect(P.add(Q).eq(Q.add(P))).toBe(true);
    expect(P.add(Q).add(R).eq(P.add(Q.add(R)))).toBe(true);
    expectMatchesReference(P.add(Q).add(R), refMul(31n));
  });

  test('adding the negation yields the point at infinity', () => {
    expect(G.add(G.neg()).isInfinity()).toBe(true);
  });

  test('neg() flips the y coordinate and is an involution', () => {
    expect(G.neg().getY().cmp(G.getY().redNeg().fromRed())).toBe(0);
    expect(G.neg().neg().eq(G)).toBe(true);
  });

  test('eq() compares coordinates and handles infinity', () => {
    expect(G.eq(G)).toBe(true);
    expect(G.eq(G.dbl())).toBe(false);
    expect(curve.point(null, null).eq(curve.point(null, null))).toBe(true);
  });

  test('inspect() renders coordinates and infinity', () => {
    expect(G.inspect()).toBe(
      '<EC Point x: ' + SECP256K1.g[0] + ' y: ' + SECP256K1.g[1] + '>'
    );
    expect(curve.point(null, null).inspect()).toBe('<EC Point Infinity>');
  });
});

describe('ShortCurve Jacobian arithmetic', () => {
  const curve = new ShortCurve(SECP256K1);
  const G = curve.g;

  test('toJ()/toP() round trip', () => {
    const jpoint = G.toJ();

    expect(jpoint.type).toBe('jacobian');
    expect(jpoint.eq(G)).toBe(true);
    expect(jpoint.toP().eq(G)).toBe(true);
  });

  test('toJ() of infinity is the Jacobian point at infinity', () => {
    const jinfinity = curve.point(null, null).toJ();

    expect(jinfinity.isInfinity()).toBe(true);
    expect(jinfinity.inspect()).toBe('<EC JPoint Infinity>');
    expect(jinfinity.toP().isInfinity()).toBe(true);
  });

  test('Jacobian addition matches affine addition', () => {
