  if (x1 === null) return p2;
  if (x2 === null) return p1;
  if (x1 === x2 && mod(y1 + y2) === 0n) return [null, null];
  let lambda;
  if (x1 === x2 && y1 === y2) {
    lambda = mod(3n * x1 * x1 + A) * invMod(2n * y1) % P;  // careful precedence
  } else {
    lambda = mod(y2 - y1) * invMod(x2 - x1) % P;
