/**
 * Behavioural tests for the Montgomery curve implementation.
 *
 * The x-only ladder is verified in two independent ways:
 *  - every produced x coordinate must satisfy the Montgomery curve equation,
 *  - the results must agree with the twisted Edwards implementation of the
 *    same field (both belong to this module).
 */
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const PROD_DIR = (() => {
  const marker = path.sep + 'test' + path.sep;
  const repoRoot = __dirname.slice(0, __dirname.indexOf(marker));
  return path.join(
    repoRoot,
    'packages/imba/polyfills/crypto/esm/lib/elliptic/lib/curve'
  );
})();

const moduleCache = new Map();

function loadModule(filename) {
  const cached = moduleCache.get(filename);
  if (cached) return cached.exports;
  const mod = { exports: {} };
  moduleCache.set(filename, mod);
  const { code } = esbuild.transformSync(fs.readFileSync(filename, 'utf8'), {
    format: 'cjs',
    loader: 'js',
    sourcefile: filename,
  });
  const dir = path.dirname(filename);
  const localRequire = (request) => {
    if (!request.startsWith('.')) return require(request);
    let target = path.resolve(dir, request);
    if (!fs.existsSync(target) && fs.existsSync(target + '.js')) target += '.js';
    return loadModule(target);
  };
  new Function('exports', 'require', 'module', '__filename', '__dirname', code)(
    mod.exports,
    localRequire,
    mod,
    filename,
    dir
  );
  return mod.exports;
}

const loadDefault = (name) => {
  const loaded = loadModule(path.join(PROD_DIR, name));
  return loaded && loaded.default ? loaded.default : loaded;
};

const MontCurve = loadDefault('mont.js');
const BaseCurve = loadDefault('base.js');
const EdwardsCurve = loadDefault('edwards.js');
const BN = loadDefault('../../../bn.js');

const P_HEX = '7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed';
const N_HEX = '1000000000000000000000000000000014def9dea2f79cd65812631a5cf5d3ed';
const A_HEX = '76d06';

const CURVE25519 = {
  prime: 'p25519',
  p: P_HEX,
  a: A_HEX,
  b: '1',
  n: N_HEX,
  g: ['9'],
};

/** ed25519 renders the same group in twisted Edwards form. */
const ED25519 = {
  prime: 'p25519',
  p: P_HEX,
  a: '-1',
  c: '1',
  d: '52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3',
  n: N_HEX,
  g: [
    '216936d3cd6e53fec0a4e231fdd6dc5c692cc7609525a7b2c9562d608f25d51a',
    '6666666666666666666666666666666666666666666666666666666666666658',
  ],
};

const P_BIG = 2n ** 255n - 19n;
const A_BIG = 486662n;

const mod = (value) => ((value % P_BIG) + P_BIG) % P_BIG;

function modPow(base, exponent, m) {
  let result = 1n;
  let b = ((base % m) + m) % m;
  let e = exponent;
  while (e > 0n) {
    if (e & 1n) result = (result * b) % m;
    b = (b * b) % m;
    e >>= 1n;
  }
  return result;
}

/** Legendre symbol check for the x coordinate of a Montgomery point. */
function isOnMontgomeryCurve(x) {
  const rhs = mod(x ** 3n + A_BIG * x * x + x);
  if (rhs === 0n) return true;
  return modPow(rhs, (P_BIG - 1n) / 2n, P_BIG) === 1n;
}

/** u = (1 + y) / (1 - y) maps an Edwards y coordinate onto the Montgomery x. */
function edwardsYToMontgomeryX(y) {
  const inverse = modPow(mod(1n - y), P_BIG - 2n, P_BIG);
  return mod((1n + y) * inverse);
}

const bigX = (point) => BigInt('0x' + point.getX().toString(16));

describe('MontCurve configuration', () => {
  test('derives the Montgomery parameters from the configuration', () => {
    const curve = new MontCurve(CURVE25519);

    expect(curve).toBeInstanceOf(BaseCurve);
    expect(curve.type).toBe('mont');
    expect(curve.a.fromRed().toString(16)).toBe(A_HEX);
    expect(curve.b.fromRed().toString()).toBe('1');
    expect(curve.i4.redMul(new BN(4).toRed(curve.red)).fromRed().cmpn(1)).toBe(0);
    expect(curve.a24.fromRed().cmp(curve.p.addn(2).divn(4))).toBe(0);
  });

  test('builds the generator from the configuration', () => {
    const curve = new MontCurve(CURVE25519);

    expect(curve.g.isInfinity()).toBe(false);
    expect(curve.g.getX().toString(16)).toBe('9');
    expect(curve.g.z.fromRed().toString()).toBe('1');
  });
});

describe('Montgomery points', () => {
  const curve = new MontCurve(CURVE25519);
  const g = curve.g;

  test('point(null, null) is the point at infinity', () => {
    const infinity = curve.point(null, null);

    expect(infinity.isInfinity()).toBe(true);
    expect(infinity.inspect()).toBe('<EC Point Infinity>');
  });

  test('inspect() renders projective coordinates', () => {
    expect(g.inspect()).toBe('<EC Point x: 9 z: 1>');
  });

  test('normalize() reduces the projective representation', () => {
    const point = curve.point(18, 2);

    expect(point.normalize()).toBe(point);
    expect(point.z.fromRed().cmpn(1)).toBe(0);
    expect(point.getX().toString()).toBe('9');
  });

  test('eq() compares the normalized x coordinates', () => {
    expect(curve.point(18, 2).eq(curve.point(9, 1))).toBe(true);
    expect(curve.point(18, 2).eq(curve.point(8, 1))).toBe(false);
  });

  test('pointFromJSON() defaults the z coordinate to one', () => {
    expect(curve.pointFromJSON(['9']).eq(g)).toBe(true);
    expect(curve.pointFromJSON(['18', '2']).eq(g)).toBe(true);
  });

  test('decodePoint() encodes and decodes the x coordinate', () => {
    const encoded = g.encode('hex');

    expect(encoded).toBe('00'.repeat(31) + '09');
    expect(g._encode()).toHaveLength(32);
    expect(curve.decodePoint(g.encode()).eq(g)).toBe(true);
    expect(curve.decodePoint(encoded, 'hex').z.fromRed().cmpn(1)).toBe(0);
  });

  test('precompute() is a no-op', () => {
    const point = curve.g.mul(new BN(2));

    expect(point.precompute()).toBeUndefined();
    expect(point.precomputed).toBeNull();
  });
});

describe('Montgomery arithmetic', () => {
  const curve = new MontCurve(CURVE25519);
  const g = curve.g;

  test('doubling agrees with repeated doubling', () => {
    expect(bigX(g.mul(new BN(2)))).toBe(bigX(g.dbl()));
    expect(bigX(g.mul(new BN(4)))).toBe(bigX(g.dbl().dbl()));
    expect(bigX(g.mul(new BN(8)))).toBe(bigX(g.dbl().dbl().dbl()));
  });

  test('the scalar 1 and the group order behave as expected', () => {
    expect(g.mul(new BN(1)).eq(g)).toBe(true);
    expect(g.mul(curve.n).isInfinity()).toBe(true);
    expect(bigX(g.mul(curve.n.addn(3)))).toBe(bigX(g.mul(new BN(3))));
  });

  test('diffAdd() adds points when the difference is supplied', () => {
    const second = g.mul(new BN(21));
    const third = g.mul(new BN(22));

    expect(bigX(second.diffAdd(third, g))).toBe(bigX(g.mul(new BN(43))));
  });

  test('every ladder result is a valid Montgomery x coordinate', () => {
    for (const scalar of [1, 2, 3, 7, 12345, 0xdeadbeef]) {
      const x = bigX(g.mul(new BN(scalar)));
      expect(isOnMontgomeryCurve(x)).toBe(true);
    }
  });

  test('ladder results are accepted by validate()', () => {
    expect(curve.validate(g)).toBe(true);
    expect(curve.validate(g.mul(new BN(9)))).toBe(true);
    expect(curve.validate(g.mul(new BN(1234567)))).toBe(true);
  });

  test('validate() throws for x coordinates that are not on the curve', () => {
    expect(() => curve.validate(curve.point(3, 1))).toThrow(/assert/i);
  });

  test('point addition is not supported', () => {
    expect(() => g.add(g)).toThrow('Not supported on Montgomery curve');
    expect(() => g.mulAdd()).toThrow('Not supported on Montgomery curve');
    expect(() => g.jumlAdd()).toThrow('Not supported on Montgomery curve');
  });
});

describe('Montgomery and Edwards representations of the same group', () => {
  const mont = new MontCurve(CURVE25519);
  const edwards = new EdwardsCurve(ED25519);

  test.each([
    ['1', 1n],
    ['2', 2n],
    ['3', 3n],
    ['7', 7n],
    ['12345', 12345n],
    ['deadbeefcafe', BigInt('0xdeadbeefcafe')],
  ])('x(%s * G) matches the Edwards representation', (_label, scalar) => {
    const montgomeryX = bigX(mont.g.mul(new BN(scalar.toString(), 10)));
    const edwardsY = BigInt(
      '0x' + edwards.g.mul(new BN(scalar.toString(), 10)).getY().toString(16)
    );

    expect(montgomeryX).toBe(edwardsYToMontgomeryX(edwardsY));
    expect(isOnMontgomeryCurve(montgomeryX)).toBe(true);
  });
});
