/**
 * Behavioural tests for the Edwards curve implementation.
 *
 * The extended (ed25519) representation is exercised through the public point
 * API, while the projective (non extended) code paths are verified against an
 * independent BigInt implementation of the twisted Edwards group law.
 */
const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const PROD_DIR = (() => {
  const marker = path.sep + 'test' + path.sep;
  const repoRoot = __dirname.slice(0, __dirname.indexOf(marker));
  return path.join(
    repoRoot,
    'packages/imba/polyfills/crypto/esm/lib/elliptic/lib/curve'
  );
})();

const moduleCache = new Map();

function loadModule(filename) {
  const cached = moduleCache.get(filename);
  if (cached) return cached.exports;
  const mod = { exports: {} };
  moduleCache.set(filename, mod);
  const { code } = esbuild.transformSync(fs.readFileSync(filename, 'utf8'), {
    format: 'cjs',
    loader: 'js',
    sourcefile: filename,
  });
  const dir = path.dirname(filename);
  const localRequire = (request) => {
    if (!request.startsWith('.')) return require(request);
    let target = path.resolve(dir, request);
    if (!fs.existsSync(target) && fs.existsSync(target + '.js')) target += '.js';
    return loadModule(target);
  };
  new Function('exports', 'require', 'module', '__filename', '__dirname', code)(
    mod.exports,
    localRequire,
    mod,
    filename,
    dir
  );
  return mod.exports;
}

const loadDefault = (name) => {
  const loaded = loadModule(path.join(PROD_DIR, name));
  return loaded && loaded.default ? loaded.default : loaded;
};

const EdwardsCurve = loadDefault('edwards.js');
const BaseCurve = loadDefault('base.js');
const BN = loadDefault('../../../bn.js');

const P_HEX = '7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed';
const N_HEX = '1000000000000000000000000000000014def9dea2f79cd65812631a5cf5d3ed';

const ED25519 = {
  prime: 'p25519',
  p: P_HEX,
  a: '-1',
  c: '1',
  d: '52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3',
  n: N_HEX,
  g: [
    '216936d3cd6e53fec0a4e231fdd6dc5c692cc7609525a7b2c9562d608f25d51a',
    '6666666666666666666666666666666666666666666666666666666666666658',
  ],
};

/**
 * Two tiny curves over GF(23) that do not use extended coordinates, so the
 * projective addition/doubling branches are covered as well.
 */
const TWISTED_CONF = { p: '17', a: '5', c: '1', d: '5', g: ['1', '1'] };
const PLAIN_CONF = { p: '17', a: '1', c: '1', d: '5', g: ['4', '11'] };

const SMALL_P = 23n;
const smallMod = (value) => ((value % SMALL_P) + SMALL_P) % SMALL_P;

function smallInverse(value) {
  let [oldR, r] = [smallMod(value), SMALL_P];
  let [oldS, s] = [1n, 0n];
  while (r !== 0n) {
    const q = oldR / r;
    [oldR, r] = [r, oldR - q * r];
    [oldS, s] = [s, oldS - q * s];
  }
  return smallMod(oldS);
}

/** Affine twisted Edwards addition for c = 1. */
function referenceAdd(first, second, a, d) {
  const [x1, y1] = first;
  const [x2, y2] = second;
  const product = smallMod(d * x1 * x2 * y1 * y2);
  const x3 = smallMod(smallMod(x1 * y2 + x2 * y1) * smallInverse(1n + product));
  const y3 = smallMod(smallMod(y1 * y2 - a * x1 * x2) * smallInverse(1n - product));
  return [x3, y3];
}

function referenceMul(point, scalar, a, d) {
  let result = [0n, 1n];
  for (let i = 0; i < scalar; i++) result = referenceAdd(result, point, a, d);
  return result;
}

const bigCoordinates = (point) => [
  BigInt('0x' + point.getX().toString(16)),
  BigInt('0x' + point.getY().toString(16)),
];

describe('EdwardsCurve configuration', () => {
  test('detects the twisted, a == -1 and extended variants', () => {
    const curve = new EdwardsCurve(ED25519);

    expect(curve).toBeInstanceOf(BaseCurve);
    expect(curve.type).toBe('edwards');
    expect(curve.twisted).toBe(true);
    expect(curve.mOneA).toBe(true);
    expect(curve.extended).toBe(true);
    expect(curve.oneC).toBe(true);
    expect(curve.a.fromRed().cmp(curve.p.subn(1))).toBe(0);
    expect(curve.c.fromRed().cmpn(1)).toBe(0);
    expect(curve.dd.fromRed().cmp(curve.d.fromRed().add(curve.d.fromRed()))).toBe(0);
  });

  test('detects a twisted curve without the a == -1 shortcut', () => {
    const curve = new EdwardsCurve(TWISTED_CONF);

    expect(curve.twisted).toBe(true);
    expect(curve.mOneA).toBe(false);
    expect(curve.extended).toBe(false);
  });

  test('detects a non twisted curve', () => {
    const curve = new EdwardsCurve(PLAIN_CONF);

    expect(curve.twisted).toBe(false);
    expect(curve.mOneA).toBe(false);
    expect(curve.extended).toBe(false);
  });

  test('builds the generator and its extended coordinate', () => {
    const curve = new EdwardsCurve(ED25519);

    expect(curve.g.getX().toString(16)).toBe(ED25519.g[0]);
    expect(curve.g.getY().toString(16)).toBe(ED25519.g[1]);
    expect(curve.g.t.fromRed().cmp(curve.g.x.redMul(curve.g.y).fromRed())).toBe(0);
  });
});

describe('Edwards point validation and recovery', () => {
  const curve = new EdwardsCurve(ED25519);

  test('validate() accepts points on the curve and the identity', () => {
    expect(curve.validate(curve.g)).toBe(true);
    expect(curve.validate(curve.g.mul(new BN(7)))).toBe(true);
    expect(curve.validate(curve.point(null, null, null))).toBe(true);
  });

  test('validate() rejects points that are not on the curve', () => {
    const offCurve = curve.point(curve.g.x, curve.g.y.redAdd(curve.one));

    expect(curve.validate(offCurve)).toBe(false);
  });

  test('pointFromY() recovers the point for the requested parity', () => {
    const odd = curve.g.getX().isOdd();

    expect(curve.pointFromY(curve.g.getY(), odd).eq(curve.g)).toBe(true);
    expect(curve.pointFromY(curve.g.getY(), !odd).eq(curve.g.neg())).toBe(true);
  });

  test('pointFromX() recovers the point for the requested parity', () => {
    const odd = curve.g.getY().isOdd();

    expect(curve.pointFromX(curve.g.getX(), odd).eq(curve.g)).toBe(true);
    expect(curve.pointFromX(curve.g.getX(), !odd).eq(curve.g.neg())).toBe(true);
  });

  test('pointFromY() rejects the degenerate x = 0 case for odd parity', () => {
    expect(() => curve.pointFromY(curve.one.fromRed(), true)).toThrow(
      'invalid point'
    );
    expect(curve.pointFromY(curve.one.fromRed(), false).isInfinity()).toBe(true);
  });
});

describe('Edwards point arithmetic', () => {
  const curve = new EdwardsCurve(ED25519);
  const g = curve.g;

  test('the point (0, 1) is the identity', () => {
    const identity = curve.point(curve.zero, curve.one);

    expect(identity.isInfinity()).toBe(true);
    expect(identity.inspect()).toBe('<EC Point Infinity>');
    expect(g.add(identity).eq(g)).toBe(true);
    expect(identity.add(g).eq(g)).toBe(true);
  });

  test('doubling agrees with adding the point to itself', () => {
    expect(g.dbl().eq(g.add(g))).toBe(true);
    expect(g.mul(new BN(2)).eq(g.dbl())).toBe(true);
  });

  test('scalar multiplication matches repeated addition', () => {
    let expected = g;
    for (let i = 0; i < 6; i++) expected = expected.add(g);
    expect(g.mul(new BN(7)).eq(expected)).toBe(true);
  });

  test('the group order brings every point back to the identity', () => {
    expect(g.mul(curve.n).isInfinity()).toBe(true);
    expect(g.mul(curve.n.subn(1)).eq(g.neg())).toBe(true);
  });

  test('neg() mirrors the x and t coordinates', () => {
    const negated = g.neg();

    expect(negated.eq(g.neg())).toBe(true);
    expect(g.add(negated).isInfinity()).toBe(true);
    expect(negated.neg().eq(g)).toBe(true);
  });

  test('eq() compares normalized coordinates', () => {
    expect(g.eq(curve.point(g.x, g.y))).toBe(true);
    expect(g.eq(g.dbl())).toBe(false);
  });

  test('normalize() keeps the affine coordinates stable', () => {
    const point = curve.point(g.x, g.y, curve.two);

    expect(point.normalize()).toBe(point);
    expect(point.getX().cmp(g.getX())).toBe(0);
    expect(point.getY().cmp(g.getY())).toBe(0);
    expect(point.zOne).toBe(true);
  });

  test('jpoint() is an alias for point() used by the generic code paths', () => {
    expect(curve.jpoint(g.x, g.y).eq(g)).toBe(true);
    expect(curve.jpoint(null, null, null).isInfinity()).toBe(true);
  });

  test('toP()/mixedAdd() stay compatible with the short curve API', () => {
    const prototype = Object.getPrototypeOf(g);

    expect(prototype.toP).toBe(prototype.normalize);
    expect(prototype.mixedAdd).toBe(prototype.add);
  });

  test('eqXToP() recognises the x coordinate of the point', () => {
    const point = g.mul(new BN(5));

    expect(point.toJ().eqXToP(point.getX())).toBe(true);
    expect(point.toJ().eqXToP(point.getX().addn(1))).toBe(false);
  });

  test('the sliding window and fixed window paths agree', () => {
    const precomputed = new EdwardsCurve(ED25519);
    precomputed.g.precompute(8);

    for (const scalar of [1, 2, 255, 0x1234]) {
      const k = new BN(scalar);
      const viaPrecomputed = precomputed.g.mul(k);
      const viaWindow = precomputed._wnafMul(precomputed.g, k);

      expect(viaPrecomputed.eq(viaWindow)).toBe(true);
    }
  });
});

describe('Edwards point encoding', () => {
  const curve = new EdwardsCurve(ED25519);
  const g = curve.g;

  test('encodes uncompressed points', () => {
    const encoded = g.encode('hex');

    expect(encoded).toBe('04' + ED25519.g[0] + ED25519.g[1]);
    expect(g.encode()).toHaveLength(65);
  });

  test('encodes compressed points with the y parity prefix', () => {
    expect(g.encodeCompressed('hex')).toBe('02' + ED25519.g[0]);
    expect(g.neg().encodeCompressed('hex')).toBe('03' + ED25519.g[0]);
  });

  test('decodes what it encoded', () => {
    expect(curve.decodePoint(g.encode()).eq(g)).toBe(true);
    expect(curve.decodePoint(g.encodeCompressed()).eq(g)).toBe(true);
    expect(curve.decodePoint(g.encode('hex'), 'hex').eq(g)).toBe(true);
  });

  test('rejects malformed encodings', () => {
    expect(() => curve.decodePoint('05' + g.encode('hex').slice(2), 'hex')).toThrow(
      'Unknown point format'
    );
    expect(() => curve.decodePoint('02' + 'ff'.repeat(31), 'hex')).toThrow(
      'Unknown point format'
    );
  });

  test('pointFromJSON() restores the projective z coordinate', () => {
    const restored = curve.pointFromJSON([ED25519.g[0], ED25519.g[1], '01']);

    expect(restored.eq(g)).toBe(true);
  });
});

describe('Edwards curves without extended coordinates', () => {
  test.each([
    ['twisted a = 5', TWISTED_CONF, 5n, 5n, [1n, 1n], 11],
    ['non twisted a = 1', PLAIN_CONF, 1n, 5n, [4n, 17n], 13],
  ])('%s multiplies correctly', (_label, conf, a, d, generator, maxScalar) => {
    const curve = new EdwardsCurve(conf);
    const g = curve.g;

    expect(curve.validate(g)).toBe(true);
    expect(g.dbl().eq(g.add(g))).toBe(true);

    for (let scalar = 1; scalar <= maxScalar; scalar++) {
      const expected = referenceMul(generator, scalar, a, d);
      const actual = curve.g.mul(new BN(scalar));
      const isIdentity = expected[0] === 0n && expected[1] === 1n;

      if (isIdentity) {
        expect(actual.isInfinity()).toBe(true);
      } else {
        const [x, y] = bigCoordinates(actual);
        expect([x, y]).toEqual(expected);
      }
    }
  });

  test('non extended curves still recover points from their coordinates', () => {
    const curve = new EdwardsCurve(TWISTED_CONF);

    expect(curve.pointFromY(curve.g.getY(), curve.g.getX().isOdd()).eq(curve.g)).toBe(
      true
    );
    expect(curve.pointFromX(curve.g.getX(), curve.g.getY().isOdd()).eq(curve.g)).toBe(
      true
    );
  });
});
