'use strict';

const { Buffer } = require('buffer');
const { loadStreamModule } = require('./stream-loader');

const BufferList = loadStreamModule('buffer-list.js').default;

describe('BufferList', () => {
  test('starts empty', () => {
    const list = new BufferList();
    expect(list.length).toBe(0);
    expect(list.shift()).toBeUndefined();
    expect(list.join('-')).toBe('');
    expect(list.concat(0).length).toBe(0);
  });

  test('push appends entries and tracks length', () => {
    const list = new BufferList();
    list.push(Buffer.from('a'));
    list.push(Buffer.from('bc'));

    expect(list.length).toBe(2);
    expect(list.join('|')).toBe('a|bc');
  });

  test('shift removes entries in FIFO order', () => {
    const list = new BufferList();
    list.push(Buffer.from('first'));
    list.push(Buffer.from('second'));

    expect(list.shift().toString()).toBe('first');
    expect(list.length).toBe(1);
    expect(list.shift().toString()).toBe('second');
    expect(list.length).toBe(0);
    expect(list.shift()).toBeUndefined();
  });

  test('unshift prepends entries and reverses access order', () => {
    const list = new BufferList();
    list.push(Buffer.from('b'));
    list.unshift(Buffer.from('a'));

    expect(list.length).toBe(2);
    expect(list.shift().toString()).toBe('a');
    expect(list.shift().toString()).toBe('b');
  });

  test('interleaved push and unshift preserve linked order', () => {
    const list = new BufferList();
    list.push(Buffer.from('middle'));
    list.unshift(Buffer.from('first'));
    list.push(Buffer.from('last'));

    expect(list.join(',')).toBe('first,middle,last');
  });

  test('clear empties the list and permits reuse', () => {
    const list = new BufferList();
    list.push(Buffer.from('one'));
    list.push(Buffer.from('two'));
    list.clear();

    expect(list.length).toBe(0);
    expect(list.join('')).toBe('');
    expect(list.shift()).toBeUndefined();

    list.push(Buffer.from('again'));
    expect(list.length).toBe(1);
    expect(list.join('')).toBe('again');
  });

  test('join works with string entries (decoded readable data)', () => {
    const list = new BufferList();
    list.push('hé');
    list.push('llo');
    expect(list.join('')).toBe('héllo');
    expect(list.join(' / ')).toBe('hé / llo');
  });

  test('concat returns a buffer with all bytes in order', () => {
    const list = new BufferList();
    list.push(Buffer.from('ab'));
    list.push(Buffer.from('cde'));

