'use strict';

const { Buffer } = require('buffer');
const { once } = require('events');
const { loadStreamModule } = require('./stream-loader');

const Writable = loadStreamModule('writable.js').default;

function wait(ms = 0) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function collectWritable(options = {}) {
  const chunks = [];
  const writable = new Writable({
    ...options,
    write(chunk, encoding, cb) {
      chunks.push(chunk);
      cb();
    }
  });
  return { writable, chunks };
}

describe('Writable', () => {
  test('can be constructed with or without new', () => {
    const withoutNew = Writable({ write(chunk, enc, cb) { cb(); } });
    const withNew = new Writable({ write(chunk, enc, cb) { cb(); } });

    expect(withoutNew).toBeInstanceOf(Writable);
    expect(withNew).toBeInstanceOf(Writable);
    expect(withoutNew.writable).toBe(true);
  });

  test('write invokes _write with a decoded buffer and calls back asynchronously', async () => {
    const seen = [];
    const writable = new Writable({
      write(chunk, encoding, cb) {
        seen.push({ chunk, encoding, hasCb: typeof cb === 'function' });
        cb();
      }
    });

    const callbackChunk = await new Promise((resolve, reject) => {
      const accepted = writable.write('hello', (err) => {
        if (err) reject(err);
        else resolve('callback');
      });
      expect(accepted).toBe(true);
    });

    expect(callbackChunk).toBe('callback');
    expect(seen).toHaveLength(1);
    expect(Buffer.isBuffer(seen[0].chunk)).toBe(true);
    expect(seen[0].chunk.toString()).toBe('hello');
    expect(seen[0].encoding).toBe('buffer');
    expect(seen[0].hasCb).toBe(true);
  });

  test('default _write reports that it is not implemented', async () => {
    const writable = new Writable();
    const errorPromise = once(writable, 'error');
    const callbackError = new Promise((resolve) => writable.write('data', resolve));

    const [error] = await errorPromise;
    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe('not implemented');
    expect((await callbackError).message).toBe('not implemented');
  });

  test('end flushes a final chunk and emits finish once', async () => {
    const { writable, chunks } = collectWritable();
    const finishes = [];
    writable.on('finish', () => finishes.push('finish'));

    const finished = once(writable, 'finish');
    writable.end('goodbye');
    await finished;
    writable.end('ignored');

    expect(chunks.map((chunk) => chunk.toString())).toEqual(['goodbye']);
    expect(finishes).toEqual(['finish']);
    expect(writable.writable).toBe(false);
    expect(writable._writableState.finished).toBe(true);
  });

  test('end callback runs after the finish event', async () => {
    const order = [];
    const writable = new Writable({
      write(chunk, enc, cb) {
        order.push('write');
        setTimeout(cb, 5);
      }
    });

    writable.on('finish', () => order.push('finish'));
    await new Promise((resolve) => writable.end(() => {
      order.push('end-callback');
      resolve();
    }));

    expect(order).toEqual(['write', 'finish', 'end-callback']);
  });

  test('write returns false at the high water mark and drain fires after flushing', async () => {
    const writable = new Writable({
      highWaterMark: 4,
      write(chunk, enc, cb) {
        setTimeout(cb, 1);
      }
    });

    const drained = once(writable, 'drain');
    expect(writable.write('abcd')).toBe(false);
    const [drainEvent] = await drained;
    expect(drainEvent).toBeUndefined();
    expect(writable._writableState.needDrain).toBe(false);
    expect(writable._writableState.length).toBe(0);
  });

  test('buffers writes while an asynchronous write is in progress', async () => {
    const processed = [];
    const callbacks = [];
    const writable = new Writable({
      write(chunk, enc, cb) {
        processed.push(chunk.toString());
        setTimeout(cb, 3);
      }
    });

    await new Promise((resolve) => {
      writable.write('a', () => callbacks.push('a'));
      writable.write('b', () => callbacks.push('b'));
      writable.end(() => {
        callbacks.push('end');
        resolve();
      });
    });

    expect(processed).toEqual(['a', 'b']);
    expect(callbacks).toEqual(['a', 'b', 'end']);
  });

  test('object mode writes arbitrary values and counts them individually', async () => {
    const objects = [];
    const first = { id: 1 };
    const second = { id: 2 };
    const writable = new Writable({
      objectMode: true,
      highWaterMark: 2,
      write(chunk, enc, cb) {
        objects.push(chunk);
        cb();
      }
    });

    expect(writable.write(first)).toBe(true);
    expect(writable.write(second)).toBe(false);
    const finished = once(writable, 'finish');
    writable.end();
    await finished;

    expect(objects).toEqual([first, second]);
    expect(objects[0]).toBe(first);
    expect(objects[1]).toBe(second);
  });

  test('rejects null and non-string/buffer chunks with a type error', async () => {
    const writable = new Writable({ write(chunk, enc, cb) { cb(); } });

    const nullError = once(writable, 'error');
    const nullCallback = new Promise((resolve) => writable.write(null, resolve));
    const [nullErr] = await nullError;
    expect(nullErr).toBeInstanceOf(TypeError);
    expect(nullErr.message).toMatch(/null/i);
    expect(await nullCallback).toBe(nullErr);

    const numberError = once(writable, 'error');
    const numberCallback = new Promise((resolve) => writable.write(42, resolve));
    const [numberErr] = await numberError;
    expect(numberErr).toBeInstanceOf(TypeError);
    expect(numberErr.message).toMatch(/non-string\/buffer/i);
    expect(await numberCallback).toBe(numberErr);
  });

  test('object mode accepts values that are invalid in byte mode', async () => {
    const values = [];
    const writable = new Writable({
      objectMode: true,
      write(chunk, enc, cb) {
        values.push(chunk);
        cb();
      }
    });

    const callback = new Promise((resolve) => writable.write(42, resolve));
    await callback;
    expect(values).toEqual([42]);
  });

  test('writing after end emits an error and does not reach _write', async () => {
    const writes = [];
    const writable = new Writable({
      write(chunk, enc, cb) {
        writes.push(chunk.toString());
        cb();
      }
    });
    const finished = once(writable, 'finish');
    writable.end();
    await finished;

    const errorPromise = once(writable, 'error');
    const callbackError = new Promise((resolve) => writable.write('late', resolve));
    const [error] = await errorPromise;

    expect(error.message).toBe('write after end');
    expect(await callbackError).toBe(error);
    expect(writes).toEqual([]);
  });

  test('cork defers writes until uncork and preserves order', async () => {
    const writes = [];
    const writable = new Writable({
      write(chunk, enc, cb) {
        writes.push(chunk.toString());
        cb();
      }
    });

    writable.cork();
    writable.write('one');
    writable.write('two');
    expect(writes).toEqual([]);

    writable.uncork();
    expect(writes).toEqual(['one', 'two']);
    await wait();
  });

  test('uses _writev for corked requests', async () => {
    const batches = [];
    const callbacks = [];
    const writable = new Writable({
      write() {
        throw new Error('individual _write should not be used');
      },
      writev(chunks, cb) {
        batches.push(chunks.map((entry) => entry.chunk.toString()));
        cb();
      }
    });

    writable.cork();
    writable.write('a', () => callbacks.push('a'));
    writable.write('b', () => callbacks.push('b'));
    writable.uncork();

    expect(batches).toEqual([['a', 'b']]);
    await wait();
    expect(callbacks).toEqual(['a', 'b']);
  });

  test('setDefaultEncoding validates and is used for string writes', async () => {
    const seen = [];
    const writable = new Writable({
      write(chunk, enc, cb) {
        seen.push({ chunk, enc });
        cb();
      }
    });

    expect(writable.setDefaultEncoding('BASE64')).toBe(writable);
    writable.write('aGk=');
    await wait();

    expect(seen[0].chunk.toString()).toBe('hi');
    expect(seen[0].enc).toBe('buffer');

    expect(() => writable.setDefaultEncoding('not-an-encoding')).toThrow(TypeError);
  });

  test('decodeStrings: false passes strings through to _write', async () => {
    const seen = [];
    const writable = new Writable({
      decodeStrings: false,
      write(chunk, enc, cb) {
        seen.push({ chunk, enc });
        cb();
      }
    });

    writable.write('plain');
    await wait();

    expect(seen[0].chunk).toBe('plain');
    expect(seen[0].enc).toBe('utf8');
  });

  test('pipe on a writable reports that it is not readable', async () => {
    const writable = new Writable({ write(chunk, enc, cb) { cb(); } });
    const errorPromise = once(writable, 'error');
    writable.pipe({});

    const [error] = await errorPromise;
    expect(error.message).toBe('Cannot pipe, not readable');
  });

  test('write callbacks receive errors from _write', async () => {
