'use strict';

const { Buffer } = require('buffer');
const { once } = require('events');
const { loadStream } = require('./stream-loader');

const { Transform, Duplex, Readable } = loadStream();

function wait(ms = 0) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function collect(stream) {
  const chunks = [];
  stream.on('data', (chunk) => chunks.push(chunk));
  return chunks;
}

describe('Transform', () => {
  test('can be constructed with or without new and is a duplex readable', () => {
    const options = {
      transform(chunk, enc, cb) { cb(null, chunk); }
    };
    const withoutNew = Transform(options);
    const withNew = new Transform(options);

    expect(withoutNew).toBeInstanceOf(Transform);
    expect(withNew).toBeInstanceOf(Transform);
    expect(withNew).toBeInstanceOf(Duplex);
    expect(withNew).toBeInstanceOf(Readable);
  });

  test('transforms every written chunk', async () => {
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        cb(null, Buffer.from(chunk.toString().toUpperCase()));
      }
    });
    const chunks = collect(transform);
    const finished = once(transform, 'finish');
    const ended = once(transform, 'end');

    transform.write('hello');
    transform.write('world');
    transform.end();
    await Promise.all([finished, ended]);

    expect(chunks.map((chunk) => chunk.toString())).toEqual(['HELLO', 'WORLD']);
  });

  test('supports asynchronous transforms while preserving order', async () => {
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        setTimeout(() => cb(null, Buffer.from(`[${chunk.toString()}]`)), 2);
      }
    });
    const chunks = collect(transform);
    const finished = once(transform, 'finish');

    transform.write('a');
    transform.write('b');
    transform.end();
    await finished;

    expect(chunks.map((chunk) => chunk.toString())).toEqual(['[a]', '[b]']);
  });

  test('a transform may push several output chunks for one input', async () => {
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        this.push(`${chunk.toString()}-one`);
        this.push(`${chunk.toString()}-two`);
        cb();
      }
    });
    const chunks = collect(transform);
    const finished = once(transform, 'finish');

    transform.end('value');
    await finished;

    expect(chunks.map((chunk) => chunk.toString())).toEqual(['value-one', 'value-two']);
  });

  test('flush appends final output before the stream ends', async () => {
    let flushCalled = 0;
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        cb(null, chunk);
      },
      flush(cb) {
        flushCalled += 1;
        this.push('-tail');
        cb();
      }
    });
    const chunks = collect(transform);
    const ended = once(transform, 'end');

    transform.end('body');
    await ended;

    expect(flushCalled).toBe(1);
    expect(chunks.map((chunk) => chunk.toString())).toEqual(['body', '-tail']);
  });

  test('object mode transforms keep values as objects', async () => {
    const transform = new Transform({
      objectMode: true,
      transform(value, encoding, cb) {
        cb(null, { value: value.value * 2 });
      }
    });
    const chunks = collect(transform);
    const finished = once(transform, 'finish');

    transform.write({ value: 2 });
    transform.write({ value: 3 });
    transform.end();
    await finished;

    expect(chunks).toEqual([{ value: 4 }, { value: 6 }]);
  });

  test('errors from the transform callback reach both error listeners and write callbacks', async () => {
    const boom = new Error('transform failed');
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        cb(boom);
      }
    });

    const errorPromise = once(transform, 'error');
    const writeCallback = new Promise((resolve) => transform.write('input', resolve));
    const [error] = await errorPromise;

    expect(error).toBe(boom);
    expect(await writeCallback).toBe(boom);
  });

  test('errors from flush are emitted as stream errors', async () => {
    const boom = new Error('flush failed');
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        cb(null, chunk);
      },
      flush(cb) {
        cb(boom);
      }
    });
    collect(transform);
    const errorPromise = once(transform, 'error');

    transform.end();
    const [error] = await errorPromise;
    expect(error).toBe(boom);
  });

  test('the base _transform is abstract', () => {
    const transform = new Transform();
    expect(() => transform.write('data')).toThrow('Not implemented');
  });

  test('reports readable and writable state transitions', async () => {
    const transform = new Transform({
      transform(chunk, encoding, cb) {
        cb(null, chunk);
      }
    });
    collect(transform);
    const finished = once(transform, 'finish');

    expect(transform.readable).toBe(true);
    expect(transform.writable).toBe(true);

    transform.end('done');
    await finished;
    await wait();

    expect(transform.writable).toBe(false);
    expect(transform.readable).toBe(false);
  });
});
