describe('comparison helpers', () => {
  test('is$ compares with loose equality and honour a custom matcher', () => {
    expect(is$(1, 1)).toBe(true);
    expect(is$('1', 1)).toBe(true);
    expect(is$(0, false)).toBe(true);
    expect(is$(null, undefined)).toBe(true);
    expect(is$(NaN, NaN)).toBe(false);

    const custom = { [matcher]: (value) => value === 'match' };
    expect(is$('match', custom)).toBe(true);
    expect(is$('nope', custom)).toBe(false);
  });

  test('isa$ supports primitive type names and Symbol.hasInstance protocols', () => {
    expect(isa$('hello', 'string')).toBe(true);
    expect(isa$(42, 'number')).toBe(true);
    expect(isa$({}, 'string')).toBe(false);

    class Base {}
    class Child extends Base {}
    expect(isa$(new Child(), Base)).toBe(true);
    expect(isa$(new Base(), Child)).toBe(false);

    const custom = { [Symbol.hasInstance]: (value) => value?.kind === 'custom' };
    expect(isa$({ kind: 'custom' }, custom)).toBe(true);
    expect(isa$({ kind: 'other' }, custom)).toBe(false);
    expect(isa$('anything', undefined)).toBeUndefined();
  });

  test('has$ prefers a custom __has__ protocol, then includes, then has', () => {
    const custom = { [__has__$]: (value) => value === 'present' };
    expect(has$('present', custom)).toBe(true);
    expect(has$('missing', custom)).toBe(false);

    expect(has$('b', ['a', 'b'])).toBe(true);
    expect(has$('z', ['a', 'b'])).toBe(false);
    expect(has$('b', new Set(['b']))).toBe(true);
    expect(has$('key', new Map([['key', 1]]))).toBe(true);
    expect(has$('ell', 'hello')).toBe(true);
    expect(has$('x', {})).toBe(false);
    expect(has$('x', null)).toBe(false);
  });

  test('idx$ uses a native indexOf or falls back to Array.prototype.indexOf', () => {
    expect(idx$(2, [1, 2, 3])).toBe(1);
    expect(idx$('b', 'abc')).toBe(1);
    expect(idx$('z', ['a', 'b'])).toBe(-1);

    function collect() {
      return idx$('b', arguments);
    }
    expect(collect('a', 'b', 'c')).toBe(1);
  });
