describe('iterable$, devlog$ and statics$', () => {
  test('iterable$ unwraps toIterable and otherwise returns the input', () => {
    const wrapped = { toIterable: () => [1, 2, 3] };
    expect(iterable$(wrapped)).toEqual([1, 2, 3]);

    const array = [4, 5];
    expect(iterable$(array)).toBe(array);
    expect(iterable$(null)).toBeUndefined();

    const nullIterable = { toIterable: () => null };
    expect(iterable$(nullIterable)).toBe(nullIterable);
  });

  test('devlog$ uses instance logger, then global logger, then identity', () => {
    const L = Symbol.for('#L');
    const local = jest.fn((args, self, ...rest) => [...args, ...rest, 'local']);
    const scoped = { [L]: local };

    expect(devlog$(['a'], scoped, 'b')).toEqual(['a', 'b', 'local']);
    expect(local).toHaveBeenCalledWith(['a'], scoped, 'b');

    const globalLogger = jest.fn((args) => [...args, 'global']);
    globalThis[L] = globalLogger;
    try {
      expect(devlog$(['a'])).toEqual(['a', 'global']);
      // An instance logger wins over the global one.
      expect(devlog$(['a'], scoped)).toEqual(['a', 'local']);
    } finally {
      delete globalThis[L];
    }

    const args = ['unchanged'];
    expect(devlog$(args)).toBe(args);
  });

