describe('Mousetrap construction and DOM integration', () => {
  test('attaches keypress, keydown and keyup listeners to the supplied target', () => {
    const target = createTarget();

    const instance = new Mousetrap(target);

    expect(instance.target).toBe(target);
    expect(target.listenerCount('keypress')).toBe(1);
    expect(target.listenerCount('keydown')).toBe(1);
    expect(target.listenerCount('keyup')).toBe(1);
  });

  test('can be called without new and defaults its target to document', () => {
    const target = createTarget();
    const fromCall = Mousetrap(target);
    expect(fromCall).toBeInstanceOf(Mousetrap);

    const instance = Mousetrap();
    expect(instance).toBeInstanceOf(Mousetrap);
    expect(instance.target).toBe(globalThis.document);
  });

  test('disables and re-enables its DOM listeners', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);

    instance.disable();
    expect(target.listenerCount('keypress')).toBe(0);
    expect(target.listenerCount('keydown')).toBe(0);
    expect(target.listenerCount('keyup')).toBe(0);

    instance.enable();
    expect(target.listenerCount('keypress')).toBe(1);
    expect(target.listenerCount('keydown')).toBe(1);
    expect(target.listenerCount('keyup')).toBe(1);
  });

  test('dispatches real keyboard events to bound callbacks', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const onA = record();
    const onEnter = record();

    instance.bind('a', onA);
    instance.bind('enter', onEnter);

    target.emit('keypress', { which: 97 });
    target.emit('keydown', { which: 13 });

    expect(onA.calls).toHaveLength(1);
    expect(onA.calls[0][0].type).toBe('keypress');
    expect(onA.calls[0][1]).toBe('a');
    expect(onEnter.calls).toHaveLength(1);
    expect(onEnter.calls[0][1]).toBe('enter');
  });

  test('normalizes keyCode-only events before matching them', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const onB = record();

    instance.bind('b', onB);
    const event = target.emit('keypress', { keyCode: 98 });

    expect(event.which).toBe(98);
    expect(onB.calls).toHaveLength(1);
  });
});

describe('bind, trigger, unbind and reset', () => {
  test('bind returns the instance and trigger invokes the registered callback', () => {
    const instance = new Mousetrap(createTarget());
    const callback = record();

    const returned = instance.bind('a', callback);
    const triggered = instance.trigger('a');

    expect(returned).toBe(instance);
    expect(triggered).toBe(instance);
    expect(callback.calls).toHaveLength(1);
    expect(callback.calls[0][0]).toEqual({});
    expect(callback.calls[0][1]).toBe('a');
  });

  test('binds an array of key combinations to one callback', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const callback = record();

    instance.bind(['a', 'b'], callback);
    target.emit('keypress', { which: 97 });
    target.emit('keypress', { which: 98 });

    expect(callback.calls.map((call) => call[1])).toEqual(['a', 'b']);
  });

  test('trigger respects the action part of the binding key', () => {
    const instance = new Mousetrap(createTarget());
    const callback = record();

    instance.bind('x', callback, 'keyup');

    instance.trigger('x');
    expect(callback.calls).toHaveLength(0);

    instance.trigger('x', 'keyup');
    expect(callback.calls).toHaveLength(1);
    expect(callback.calls[0][1]).toBe('x');
  });

  test('triggering an unbound combination is a harmless no-op', () => {
    const instance = new Mousetrap(createTarget());

    expect(() => instance.trigger('never-bound')).not.toThrow();
    expect(instance.trigger('never-bound')).toBe(instance);
  });

  test('unbind replaces the callback with a no-op', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const callback = record();

    instance.bind('a', callback);
    instance.unbind('a');

    instance.trigger('a');
    target.emit('keypress', { which: 97 });

    expect(callback.calls).toHaveLength(0);
  });

  test('a later binding for the same combination replaces the earlier callback', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const first = record();
    const second = record();

    instance.bind('a', first);
    instance.bind('a', second);
    target.emit('keypress', { which: 97 });

    expect(first.calls).toHaveLength(0);
    expect(second.calls).toHaveLength(1);
  });

  test('reset removes every binding and returns the instance', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const callback = record();

    instance.bind('a', callback);
    expect(instance.reset()).toBe(instance);

    instance.trigger('a');
    target.emit('keypress', { which: 97 });

    expect(callback.calls).toHaveLength(0);
  });
});

describe('key actions, modifiers and aliases', () => {
