    expect(callback.calls).toHaveLength(0);

    target.emit('keypress', { which: 97 });
    expect(callback.calls).toHaveLength(1);
  });

  test('special keys such as enter default to keydown', () => {
    const target = createTarget();
    const instance = new Mousetrap(target);
    const callback = record();

    instance.bind('enter', callback);
    target.emit('keypress', { which: 13 });
    expect(callback.calls).toHaveLength(0);

    target.emit('keydown', { which: 13 });
    expect(callback.calls).toHaveLength(1);
  });

  test('modified combinations default to keydown and require their modifiers', () => {
