const HMR_PATH = '../../../../../packages/imba/src/imba/hmr.js';

let eventSourceInstances;
let originalEventSource;
let originalDocument;
let originalLoaded;
let originalDevtools;

class FakeEventSource {
  constructor(url) {
    this.url = url;
    this.listeners = {};
    this.onmessage = null;
    this.onerror = null;
    this.closed = false;
    this.close = jest.fn(() => {
      this.closed = true;
    });
    eventSourceInstances.push(this);
  }

  addEventListener(type, listener) {
    if (!this.listeners[type]) this.listeners[type] = [];
    this.listeners[type].push(listener);
  }

  emit(type, data) {
    for (const listener of this.listeners[type] || []) {
      listener({ type, data });
    }
  }
}

function makeDocument() {
  return {
    styleSheets: [],
    location: { reload: jest.fn() },
  };
}

function loadDevtools() {
  jest.resetModules();
  delete globalThis.imba_devtools;
  globalThis.EventSource = FakeEventSource;
  globalThis.document = makeDocument();
  globalThis.IMBA_LOADED = {};
  require(HMR_PATH);
  return globalThis.imba_devtools;
}

function makeSheet(href) {
  return {
    ownerNode: {
      href,
      getAttribute: jest.fn(() => href),
    },
  };
}

beforeEach(() => {
  originalEventSource = globalThis.EventSource;
  originalDocument = globalThis.document;
  originalLoaded = globalThis.IMBA_LOADED;
  originalDevtools = globalThis.imba_devtools;
  eventSourceInstances = [];
});

afterEach(() => {
  jest.useRealTimers();
  jest.restoreAllMocks();

  if (originalEventSource === undefined) delete globalThis.EventSource;
  else globalThis.EventSource = originalEventSource;

  if (originalDocument === undefined) delete globalThis.document;
  else globalThis.document = originalDocument;

  if (originalLoaded === undefined) delete globalThis.IMBA_LOADED;
  else globalThis.IMBA_LOADED = originalLoaded;

  if (originalDevtools === undefined) delete globalThis.imba_devtools;
  else globalThis.imba_devtools = originalDevtools;
});

describe('HMR bootstrap', () => {
  test('publishes imba_devtools and opens one EventSource connection', () => {
    const devtools = loadDevtools();

    expect(devtools).toBeDefined();
    expect(devtools.debug).toBe(false);
    expect(eventSourceInstances).toHaveLength(1);
    expect(devtools.socket).toBe(eventSourceInstances[0]);
    expect(devtools.socket.url).toBe('/__hmr__');
    expect(devtools.manifest).toBeUndefined();
  });

  test('start is idempotent while a socket is already open', () => {
    const devtools = loadDevtools();

    devtools.start();

    expect(eventSourceInstances).toHaveLength(1);
    expect(devtools.socket).toBe(eventSourceInstances[0]);
  });

  test('log always forwards to console.log', () => {
    const devtools = loadDevtools();
    const log = jest.spyOn(console, 'log').mockImplementation(() => {});
    const payload = { hello: 'world' };

    devtools.log('prefix', payload);

    expect(log).toHaveBeenCalledWith('prefix', payload);
  });
});

describe('refresh', () => {
